184	// On non-Unix targets keygen never reaches the filesystem; keep the message
185	// rendering lossy-but-inert there (control bytes are still escaped) rather
186	// than duplicating the byte-level renderer.
187	#[cfg(not(unix))]
188	fn render_path(path: &OsStr) -> String {
189	    use std::fmt::Write as _;
190	    let text = path.to_string_lossy();
191	    if text
192	        .chars()
193	        .all(|c| c as u32 >= 0x20 && c != '"' && c != '\\' && c as u32 != 0x7f)
194	    {
195	        return text.into_owned();
196	    }
197	    let mut out = String::with_capacity(text.len() + 2);
198	    out.push('"');
199	    for c in text.chars() {
200	        match c {
201	            '\n' => out.push_str("\\n"),
202	            '\r' => out.push_str("\\r"),
203	            '\t' => out.push_str("\\t"),
204	            '"' => out.push_str("\\\""),
205	            '\\' => out.push_str("\\\\"),
206	            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
207	                let _ = write!(out, "\\x{:02x}", c as u32);
208	            }
209	            c => out.push(c),
210	        }
211	    }
212	    out.push('"');
213	    out
214	}
