311	#[cfg(unix)]
312	fn generate_key_file(path: &OsStr) -> std::io::Result<()> {
313	    // Use the raw OS bytes so a path containing non-UTF-8 bytes refers to
314	    // exactly the name the user passed, with no lossy substitution.
315	    let c_path = CString::new(path.as_bytes()).map_err(|_| {
316	        std::io::Error::new(
317	            std::io::ErrorKind::InvalidInput,
318	            "target path contains a NUL byte",
319	        )
320	    })?;
321	
322	    // This stack array is the only buffer this command directly holds that
323	    // contains the generated key material: getrandom draws straight into it
324	    // (the crate forwards the buffer to the getrandom(2) syscall without
325	    // copying it) and the save code only ever borrows it. Whatever happens
326	    // below -- success, a random-source failure after zero, some, or all 32
327	    // bytes, or a failure creating/permissioning/writing/closing the file --
328	    // the array is wiped before this operation returns, and the wipe must
329	    // survive an optimizing compiler. It therefore lives here in this
330	    // wrapper rather than at the individual return sites, so no error branch
331	    // inside the save logic can bypass it.
332	    let mut key = [0u8; KEY_LEN];
333	    let outcome = save_key_file(&c_path, path, &mut key);
334	    secure_zero(&mut key);
335	    outcome
336	}
