338	#[cfg(unix)]
339	fn save_key_file(
340	    c_path: &CString,
341	    path: &OsStr,
342	    key: &mut [u8; KEY_LEN],
343	) -> std::io::Result<()> {
344	    // Draw the key from the OS CSPRNG first. If the random source is
345	    // unavailable nothing is ever created at the target path. Bytes already
346	    // delivered on a mid-draw failure are secret material even though no
347	    // complete key exists: they are wiped by the caller on the way out, and
348	    // they are neither zero-padded into a stand-in key nor reported.
349	    if let Err(e) = getrandom::fill(key) {
350	        return Err(std::io::Error::new(
351	            std::io::ErrorKind::Other,
352	            format!("cryptographic random source unavailable: {e}"),
353	        ));
354	    }
355	
356	    // O_CREAT | O_EXCL: fail if anything already exists at the path (file,
357	    // directory, or symlink -- including a dangling one, which O_NOFOLLOW
358	    // also rejects), so a pre-existing object is never overwritten or
359	    // followed. mode 0600 contains no group/other bits, and the umask can
360	    // only strip bits, never add them: group/other therefore never gain
361	    // access, not even for an instant. A strict umask (e.g. 0777) can also
362	    // strip the owner bits, leaving 0000; that is repaired with fchmod and
363	    // verified before any key byte is written (see ensure_owner_only_mode).
364	    let fd = unsafe {
365	        libc::open(
366	            c_path.as_ptr(),
367	            libc::O_WRONLY
368	                | libc::O_CREAT
369	                | libc::O_EXCL
370	                | libc::O_NOFOLLOW
371	                | libc::O_CLOEXEC,
372	            0o600,
373	        )
374	    };
375	    if fd < 0 {
376	        let e = std::io::Error::last_os_error();
377	        return Err(std::io::Error::new(
378	            e.kind(),
379	            format!("cannot create key file {}: {e}", render_path(path)),
380	        ));
381	    }
382	    let fd = fd as RawFd;
383	
384	    // Enforce and confirm exactly 0600 before writing, then write and fsync.
385	    // On any failure the inode we just created is unlinked by abort_save; an
386	    // object predating this invocation is never touched. The key buffer is
387	    // wiped by generate_key_file on the way out of every arm below --
388	    // including the close-failure arm -- so it is not zeroed here.
389	    let outcome = ensure_owner_only_mode(fd).and_then(|()| write_key(fd, key));
390	
391	    match outcome {
392	        // The descriptor is still open: abort_save unlinks while it is (only
393	        // the link to the inode we just created is removed) and closes it
394	        // afterwards.
395	        Err(stage) => Err(abort_save(&c_path, path, Some(fd), stage)),
396	        Ok(()) => {
397	            // All 32 bytes were written and fsynced, but the save is only
398	            // finished once the close succeeds.
399	            if unsafe { libc::close(fd) } == 0 {
400	                return Ok(());
401	            }
402	            let e = std::io::Error::last_os_error();
403	            if e.raw_os_error() == Some(libc::EINTR) {
404	                // close() released the descriptor despite EINTR.
405	                return Ok(());
406	            }
407	            // An unrecoverable close error: even if the file happens to hold
408	            // 32 bytes with mode 0600, the save did not complete normally, so
409	            // this invocation's file must not stay behind to be mistaken for
410	            // a successfully saved key. On Linux the descriptor is released
411	            // even when close() reports an error, so close is not retried;
412	            // the file is removed exactly as for a write or fsync failure.
413	            let stage = std::io::Error::new(
414	                e.kind(),
415	                format!("closing the key file failed: {e}"),
416	            );
417	            Err(abort_save(&c_path, path, None, stage))
418	        }
419	    }
420	}
