450	/// Abandon a save that could not be completed: remove the file this
451	/// invocation created at the target and build the error to report.
452	///
453	/// `stage` is the original failure (permission setup or confirmation, write,
454	/// sync, or close); its kind and message are kept as the reported error, so a
455	/// cleanup problem can never mask why the save failed. If `fd` is `Some`, the
456	/// descriptor is still open: the unlink runs first and its result is captured
457	/// before the close, which may clobber errno (on Linux close releases the
458	/// descriptor even when it reports an error, so it is never retried).
459	///
460	/// The unlink only ever targets the link this invocation created (the caller
461	/// opened it O_CREAT | O_EXCL), never an object that predates this run.
462	///
463	/// * Removal succeeds: nothing of this run remains at the target -- no empty
464	///   file, no partial key, no unsynced 32-byte file.
465	/// * The system refuses the removal: whatever the file holds (an empty file,
466	///   a partial key, or 32 bytes that were never synced), it is not a saved
467	///   key. The report keeps the original failure, adds the cleanup failure
468	///   and its reason, and says plainly that this run's file may still sit at
469	///   the target so the user can check and remove it. It never claims the
470	///   file is gone, and the refusal is never worked around -- the parent
471	///   directory's permissions are not loosened and the key is not stashed
472	///   under another name.
473	#[cfg(unix)]
474	fn abort_save(
475	    c_path: &CString,
476	    path: &OsStr,
477	    fd: Option<RawFd>,
478	    stage: std::io::Error,
479	) -> std::io::Error {
480	    let unlink_err = if unsafe { libc::unlink(c_path.as_ptr()) } == 0 {
481	        None
482	    } else {
483	        Some(std::io::Error::last_os_error())
484	    };
485	    if let Some(fd) = fd {
486	        unsafe { libc::close(fd) };
487	    }
488	    let kind = stage.kind();
489	    match unlink_err {
490	        None => std::io::Error::new(
491	            kind,
492	            format!(
493	                "key file {} was not saved: {stage}; the file created by \
494	                 this invocation has been removed",
495	                render_path(path)
496	            ),
497	        ),
498	        Some(ue) => std::io::Error::new(
499	            kind,
500	            format!(
501	                "key file {} was not saved: {stage}; cleanup of the \
502	                 incomplete file also failed ({ue}): a file created by this \
503	                 failed run may still be present at the target -- check and \
504	                 remove it yourself",
505	                render_path(path)
506	            ),
507	        ),
508	    }
509	}
