1	//! Regression coverage for the temporary key's in-memory lifecycle on Unix:
2	//! the 32 bytes the OS random source delivers are held directly in one
3	//! stack buffer while the key is saved, and that whole buffer is overwritten
4	//! with zeroes *before the keygen operation returns* -- under both the
5	//! unoptimized and the optimized (release) build.
6	//!
7	//! Why this needs more than the existing tests
8	//! --------------------------------------------
9	//! File deletion, an empty stdout/stderr, and a 0/1 exit code cannot prove
10	//! the wipe happened: the whole process image vanishes on exit, and even a
11	//! still-secret stack slot could be overwritten later by an unrelated frame.
12	//! The promise in README ("内存中的临时密钥清零") is about the buffer that
13	//! directly held the random bytes while the operation was in flight, so the
14	//! buffer has to be inspected *during* the run:
15	//!
16	//!   * that non-zero secret bytes really were delivered and really were
17	//!     held through the save (the saved file must still be that exact key,
18	//!     not zeroes and not truncated);
19	//!   * and that those bytes were all overwritten before the operation
20	//!     returned (in particular before its stdout/stderr report).
21	//!
22	//! The tests drive the real wrapfile binary under
23	//! `tests/support/keylife/keylife`, an *external* ptrace observer (not an
24	//! LD_PRELOAD shim): it forks, its child PTRACE_TRACEME's itself and execs
25	//! wrapfile, and the observer locates the 32-byte buffer at the getrandom
26	//! syscall, reads it across the file operations, and single-steps the guest
27	//! after the save (success), after the emulated random-source failure, and
28	//! after a mid-save write failure to watch the whole buffer become zero
29	//! before the first stdout/stderr write. For a partial-draw failure it also
30	//! plants a non-zero sentinel in the slots the random source never delivered
31	//! (those slots stay zero from initialization), so a wipe covering only the
32	//! delivered prefix is caught too.
33	//!
34	//! The random source is made deterministic and fail-able by the existing
35	//! randtrap shim (fixed 0x80.. byte pattern; seccomp SIGSYS emulation), and
36	//! the write failure by the existing permfail shim. Nothing in the product
37	//! changes.
38	//!
39	//! Every scenario is run against the debug binary (`CARGO_BIN_EXE_wrapfile`)
40	//! and a freshly built `--release` binary, since an optimizer deleting a
41	//! dead plain `fill(0)` is precisely one of the regressions this guards.
42	#![cfg(unix)]
43	
44	mod common;
45	
46	use std::collections::HashMap;
47	use std::fs;
48	use std::os::unix::fs::{MetadataExt, PermissionsExt};
49	use std::path::{Path, PathBuf};
50	use std::process::Command;
51	use std::sync::atomic::{AtomicU64, Ordering};
52	
53	const KEY_LEN: usize = 32;
54	const MODE_0600: u32 = 0o600;
55	
56	// ---------------------------------------------------------------------------
57	// binaries: the profile under which `cargo test` runs, plus a release build
58	// ---------------------------------------------------------------------------
59	
60	fn debug_bin() -> PathBuf {
61	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
62	}
63	
64	/// Ensure a release/optimized wrapfile is available and return its path.
65	/// `None` (reason printed) if one cannot be produced here, so the release
66	/// cases skip instead of failing.
67	///
68	/// When the tests themselves run under `cargo test --release`, the test
69	/// binary already lives in target/release and that wrapfile is reused.
70	/// Otherwise a release wrapfile is built into a *separate* target
71	/// directory under CARGO_TARGET_TMPDIR: running `cargo build` against the
72	/// main target dir from inside a test would block on Cargo's target lock
73	/// for as long as the whole test process runs (a self-deadlock).
74	fn release_bin() -> Option<PathBuf> {
75	    static READY: std::sync::OnceLock<Option<PathBuf>> = std::sync::OnceLock::new();
76	    READY.get_or_init(|| {
77	        let debug = debug_bin();
78	        if debug
79	            .components()
80	            .any(|c| c.as_os_str() == "release")
81	        {
82	            return Some(debug);
83	        }
84	
85	        let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
86	        let scratch = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
87	            .join("wrapfile-release-for-zeroing-tests");
88	        let _ = fs::create_dir_all(&scratch);
89	        let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
90	        let status = Command::new(&cargo)
91	            .args(["build", "--release", "--offline", "--quiet"])
92	            .current_dir(&manifest)
93	            .env("CARGO_TARGET_DIR", &scratch)
94	            .status();
95	        let path = scratch.join("release").join("wrapfile");
96	        match status {
97	            Ok(s) if s.success() && path.is_file() => Some(path),
98	            Ok(s) => {
99	                eprintln!(
100	                    "skipping release-profile zeroing cases: building the \
101	                     release guest exited with {s}"
102	                );
103	                None
104	            }
105	            Err(e) => {
106	                eprintln!(
107	                    "skipping release-profile zeroing cases: cannot run \
108	                     `{cargo}` to build the release guest: {e}"
109	                );
110	                None
111	            }
112	        }
113	    })
114	    .clone()
115	}
116	
117	// ---------------------------------------------------------------------------
118	// scratch directory
119	// ---------------------------------------------------------------------------
120	
121	struct Tmp {
122	    path: PathBuf,
123	}
124	
125	impl Tmp {
126	    fn new(label: &str) -> Tmp {
127	        static SEQ: AtomicU64 = AtomicU64::new(0);
128	        let path = std::env::temp_dir().join(format!(
129	            "wrapfile-keygen-zeroing-tests-{}-{}-{}",
130	            std::process::id(),
131	            label,
132	            SEQ.fetch_add(1, Ordering::Relaxed)
133	        ));
134	        fs::create_dir_all(&path).unwrap();
135	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
136	        Tmp { path }
137	    }
138	
139	    fn child(&self, name: &str) -> PathBuf {
140	        self.path.join(name)
141	    }
142	}
143	
144	impl Drop for Tmp {
145	    fn drop(&mut self) {
146	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
147	        let _ = fs::remove_dir_all(&self.path);
148	    }
149	}
150	
151	// ---------------------------------------------------------------------------
152	// observer event stream
153	// ---------------------------------------------------------------------------
154	
155	#[derive(Debug, Clone)]
156	struct Event {
157	    name: String,
158	    attrs: HashMap<String, String>,
159	}
160	
161	impl Event {
162	    fn get(&self, key: &str) -> Option<&str> {
163	        self.attrs.get(key).map(String::as_str)
164	    }
165	    fn usize(&self, key: &str) -> Option<usize> {
166	        self.get(key).and_then(|v| v.parse().ok())
167	    }
168	    fn i64(&self, key: &str) -> Option<i64> {
169	        self.get(key).and_then(|v| v.parse().ok())
170	    }
171	}
172	
173	struct Observation {
174	    rc: i32,
175	    observer_err: String,
176	    events: Vec<Event>,
177	    fail: Option<String>,
178	}
179	
180	impl Observation {
181	    fn named(&self, name: &str) -> Vec<&Event> {
182	        self.events.iter().filter(|e| e.name == name).collect()
183	    }
184	    fn first(&self, name: &str) -> Option<&Event> {
185	        self.events.iter().find(|e| e.name == name)
186	    }
187	    fn index(&self, name: &str) -> Option<usize> {
188	        self.events.iter().position(|e| e.name == name)
189	    }
190	    fn secret(&self) -> Vec<u8> {
191	        let hex = self
192	            .first("FILL_COMPLETE")
193	            .and_then(|e| e.get("secret"))
194	            .expect("FILL_COMPLETE secret=");
195	        assert_eq!(hex.len() % 2, 0);
196	        (0..hex.len() / 2)
197	            .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
198	            .collect()
199	    }
200	}
201	
202	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
203	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
204	}
205	
206	fn parse_events(stdout: &[u8]) -> Vec<Event> {
207	    String::from_utf8_lossy(stdout)
208	        .lines()
209	        .filter_map(|line| {
210	            let mut it = line.split_whitespace();
211	            let tag = it.next()?;
212	            if tag != "EVENT" {
213	                return None;
214	            }
215	            let mut attrs = HashMap::new();
216	            let mut name = String::new();
217	            for kv in it {
218	                let (k, v) = kv.split_once('=')?;
219	                if k == "name" {
220	                    name = v.to_string();
221	                } else {
222	                    attrs.insert(k.to_string(), v.to_string());
223	                }
224	            }
225	            (!name.is_empty()).then_some(Event { name, attrs })
226	        })
227	        .collect()
228	}
229	
230	fn fail_reason(stdout: &[u8]) -> Option<String> {
231	    String::from_utf8_lossy(stdout)
232	        .lines()
233	        .find_map(|l| l.strip_prefix("FAIL reason=").map(str::to_string))
234	}
235	
236	/// Run the keylife observer around `wrapfile keygen <key>` with the given
237	/// LD_PRELOAD libraries and extra environment.
238	fn observe(
239	    observer: &Path,
240	    bin: &Path,
241	    scenario: &str,
242	    key: &Path,
243	    preloads: &[PathBuf],
244	    extra_env: &[(&str, &str)],
245	    trace: &Path,
246	) -> Observation {
247	    let dir = key.parent().unwrap();
248	    let out_cap = dir.join("guest.stdout");
249	    let err_cap = dir.join("guest.stderr");
250	    for f in [&out_cap, &err_cap] {
251	        let _ = fs::remove_file(f);
252	    }
253	
254	    let preload = preloads
255	        .iter()
256	        .map(|p| p.display().to_string())
257	        .collect::<Vec<_>>()
258	        .join(":");
259	
260	    let output = Command::new(observer)
261	        .arg(scenario)
262	        .arg(&out_cap)
263	        .arg(&err_cap)
264	        .arg("--")
265	        .arg(bin)
266	        .arg("keygen")
267	        .arg(key)
268	        .env("LD_PRELOAD", preload)
269	        .env("WRAPFILE_TEST_TRACE_FILE", trace)
270	        .envs(extra_env.iter().copied())
271	        .output()
272	        .expect("run keylife observer");
273	
274	    Observation {
275	        rc: output.status.code().unwrap_or(-1),
276	        observer_err: String::from_utf8_lossy(&output.stderr).into_owned(),
277	        events: parse_events(&output.stdout),
278	        fail: fail_reason(&output.stdout),
279	    }
280	}
281	
282	fn guest_captured(key: &Path) -> (Vec<u8>, Vec<u8>) {
283	    let dir = key.parent().unwrap();
284	    let out = fs::read(dir.join("guest.stdout")).unwrap_or_default();
285	    let err = fs::read(dir.join("guest.stderr")).unwrap_or_default();
286	    (out, err)
287	}
288	
289	// ---------------------------------------------------------------------------
290	// shim / observer availability
291	// ---------------------------------------------------------------------------
292	
293	struct Support {
294	    observer: PathBuf,
295	    randtrap: PathBuf,
296	    permfail: PathBuf,
297	}
298	
299	fn support() -> Option<Support> {
300	    let observer = common::keylife_bin()?;
301	    let randtrap = common::randtrap_so()?;
302	    let permfail = common::permfail_so()?;
303	    Some(Support { observer, randtrap, permfail })
304	}
305	
306	/// True when the randtrap shim armed its seccomp trap in the guest (a
307	/// machine without seccomp must skip, not fail).
308	fn trap_armed(trace: &Path) -> bool {
309	    match fs::read_to_string(trace) {
310	        Ok(t) => t.lines().any(|l| l == "TRAP armed"),
311	        Err(_) => false,
312	    }
313	}
314	
315	// ---------------------------------------------------------------------------
316	// randtrap trace helpers
317	// ---------------------------------------------------------------------------
318	
319	#[derive(Debug)]
320	struct GrEvent {
321	    req: usize,
322	    base: usize,
323	    ret: i64,
324	}
325	
326	fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
327	    let text = fs::read_to_string(trace).unwrap();
328	    text.lines()
329	        .filter_map(|line| {
330	            let mut parts = line.split_whitespace();
331	            if parts.next() != Some("GETRANDOM") {
332	                return None;
333	            }
334	            let mut req = None;
335	            let mut base = None;
336	            let mut ret = None;
337	            for kv in parts {
338	                let (k, v) = kv.split_once('=')?;
339	                match k {
340	                    "req" => req = v.parse().ok(),
341	                    "base" => base = v.parse().ok(),
342	                    "ret" => ret = v.parse().ok(),
343	                    _ => {}
344	                }
345	            }
346	            Some(GrEvent { req: req?, base: base?, ret: ret? })
347	        })
348	        .collect()
349	}
350	
351	fn pattern_byte(i: usize) -> u8 {
352	    (0x80 + (i % 64)) as u8
353	}
354	
355	/// The random bytes the key fill received, reconstructed from the trace.
356	fn key_fill_bytes(events: &[GrEvent]) -> Vec<u8> {
357	    let start = events
358	        .iter()
359	        .rposition(|e| e.req == KEY_LEN)
360	        .expect("keygen must draw the 32 key bytes");
361	    events[start..]
362	        .iter()
363	        .filter(|e| e.ret > 0)
364	        .flat_map(|e| (0..e.ret as usize).map(move |i| pattern_byte(e.base + i)))
365	        .collect()
366	}
367	
368	/// Global draw index at which keygen's own 32-byte fill starts: the `base`
369	/// of its first (req=32) call. Bytes before that are the process runtime's
370	/// own startup consumption and vary across environments, so a fail-after-N
371	/// scenario is calibrated from this instead of a hard-coded N.
372	fn key_fill_base(events: &[GrEvent]) -> usize {
373	    events
374	        .iter()
375	        .rposition(|e| e.req == KEY_LEN)
376	        .map(|i| events[i].base)
377	        .expect("keygen must draw the 32 key bytes")
378	}
379	
380	// ---------------------------------------------------------------------------
381	// filesystem helpers
382	// ---------------------------------------------------------------------------
383	
384	fn mode_of(path: &Path) -> u32 {
385	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
386	}
387	
388	fn make_sibling(dir: &Path) -> (PathBuf, Vec<u8>, u32) {
389	    let p = dir.join("sibling");
390	    let bytes: Vec<u8> = (0..32).map(|i| b'a' + (i % 26) as u8).collect();
391	    fs::write(&p, &bytes).unwrap();
392	    fs::set_permissions(&p, fs::Permissions::from_mode(0o640)).unwrap();
393	    (p, bytes, 0o640)
394	}
395	
396	fn assert_sentinel_untouched(path: &Path, bytes: &[u8], mode: u32) {
397	    let meta = fs::metadata(path).unwrap();
398	    assert_eq!(meta.mode() & 0o7777, mode, "sibling permissions changed");
399	    assert_eq!(fs::read(path).unwrap(), bytes, "sibling contents changed");
400	}
401	
402	// Every scenario needs the observer to run successfully (rc 0) and reach a
403	// guest exit. rc 2 means the observer itself could not run in this
404	// environment (e.g. ptrace forbidden): the caller skips.
405	fn observer_ran(obs: &Observation) -> bool {
406	    if obs.rc == 2 {
407	        eprintln!(
408	            "skipping: keylife observer could not run here: {}",
409	            obs.observer_err.trim()
410	        );
411	        false
412	    } else {
413	        true
414	    }
415	}
416	
417	// ---------------------------------------------------------------------------
418	// scenarios, parameterized by the guest binary (debug / release)
419	// ---------------------------------------------------------------------------
420	
421	fn success_wipes_full_key_and_saves_it_intact(sup: &Support, bin: &Path, profile: &str) {
422	    let tmp = Tmp::new(&format!("success-{profile}"));
423	    let key = tmp.child("key");
424	    let trace = tmp.child("trace.log");
425	    fs::File::create(&trace).unwrap();
426	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
427	
428	    // Short, always-successful reads from the deterministic source: not a
429	    // failure, and every delivered byte is recognisable in memory/file.
430	    let obs = observe(
431	        &sup.observer,
432	        bin,
433	        "success",
434	        &key,
435	        &[sup.randtrap.clone()],
436	        &[("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8")],
437	        &trace,
438	    );
439	    if !observer_ran(&obs) {
440	        return;
441	    }
442	    if !trap_armed(&trace) {
443	        eprintln!("skipping: randtrap seccomp trap did not arm here");
444	        return;
445	    }
446	    assert_eq!(
447	        obs.rc, 0,
448	        "[{profile}] observer must report success, got FAIL: {:?}",
449	        obs.fail.clone()
450	    );
451	
452	    // (1) Non-zero secret really was delivered into the one buffer...
453	    let fill = obs
454	        .first("FILL_COMPLETE")
455	        .expect("FILL_COMPLETE event");
456	    assert_eq!(fill.usize("held"), Some(KEY_LEN));
457	    let secret = obs.secret();
458	    assert_eq!(secret.len(), KEY_LEN);
459	    assert!(
460	        secret.iter().all(|&b| b != 0),
461	        "the held key must consist of non-zero delivered bytes"
462	    );
463	    // ...and matches what the random source actually handed keygen.
464	    let delivered = key_fill_bytes(&getrandom_events(&trace));
465	    assert_eq!(delivered.len(), KEY_LEN);
466	    assert_eq!(secret, delivered, "observed buffer bytes must equal delivery");
467	
468	    // (2) The same live bytes were borrowed for the save (never zeroed
469	    // before/during), and were still present when close returned.
470	    assert!(!obs.named("WRITE_BORROWS").is_empty(), "key writes must be seen");
471	    assert!(obs.first("CLOSE_STILL_HELD").is_some());
472	
473	    // (3) The whole 32-byte buffer was zeroed in a tight local loop before
474	    // the first stdout/stderr write -- and before the operation returned.
475	    let wiped = obs.first("WIPED").expect("WIPED event");
476	    assert_eq!(wiped.usize("held"), Some(KEY_LEN));
477	    assert_eq!(wiped.usize("sentinel"), Some(0));
478	    let steps = wiped.i64("steps").expect("WIPED steps=");
479	    assert!(
480	        (1..1_000_000).contains(&steps),
481	        "wipe must be a small bounded local loop, got {steps} steps"
482	    );
483	    let i_wiped = obs.index("WIPED").unwrap();
484	    let i_output = obs
485	        .index("OUTPUT_AFTER_WIPE")
486	        .expect("a post-wipe stdout/stderr write must be seen");
487	    let i_close = obs.index("CLOSE_STILL_HELD").unwrap();
488	    assert!(i_close < i_wiped, "wipe must follow the save's close");
489	    assert!(i_wiped < i_output, "wipe must precede the success report");
490	
491	    let guest_exit = obs
492	        .first("GUEST_EXIT")
493	        .and_then(|e| e.i64("rc"))
494	        .expect("guest exit event");
495	    assert_eq!(guest_exit, 0);
496	
497	    // Public behavior is unchanged: exactly the delivered 32 bytes, mode
498	    // exactly 0600, stdout only the save-location line, stderr empty.
499	    let on_disk = fs::read(&key).expect("key file must exist");
500	    assert_eq!(on_disk.len(), KEY_LEN);
501	    assert_eq!(on_disk, secret, "the saved key must be the delivered bytes");
502	    assert_eq!(mode_of(&key), MODE_0600, "key file mode must be exactly 0600");
503	
504	    let (out, err) = guest_captured(&key);
505	    assert!(err.is_empty(), "stderr must be empty on success: {err:?}");
506	    assert_eq!(
507	        out,
508	        format!("Key saved to {}\n", key.display()).into_bytes()
509	    );
510	}
511	
512	fn partial_random_failure_wipes_fragment_and_entire_buffer(
513	    sup: &Support,
514	    bin: &Path,
515	    profile: &str,
516	) {
517	    let tmp = Tmp::new(&format!("randfail-{profile}"));
518	    let key = tmp.child("key");
519	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
520	    let parent_before = mode_of(&tmp.path);
521	    let trace = tmp.child("trace.log");
522	    fs::File::create(&trace).unwrap();
523	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
524	
525	    // Calibrate where keygen's own 32-byte fill starts in the shim's global
526	    // draw counter. The process runtime draws some bytes of its own first,
527	    // and that amount must not be hard-coded; it also depends on the fault
528	    // semantics (a PARTIAL limit truncates the runtime's own call while a
529	    // FAIL_AFTER cutoff does not), so the probe uses the *same* FAIL_AFTER
530	    // mechanism with a quota far beyond anything the process will draw: the
531	    // guest completes normally and its trace records the fill's base. The
532	    // real fault run then cuts the source a fixed number of bytes into the
533	    // fill.
534	    const TARGET_FRAGMENT: usize = 13;
535	    let cal_dir = Tmp::new(&format!("randfail-cal-{profile}"));
536	    let cal_key = cal_dir.child("cal");
537	    let cal_trace = cal_dir.child("trace.log");
538	    fs::File::create(&cal_trace).unwrap();
539	    fs::set_permissions(&cal_trace, fs::Permissions::from_mode(0o644)).unwrap();
540	    let cal = observe(
541	        &sup.observer,
542	        bin,
543	        "success",
544	        &cal_key,
545	        &[sup.randtrap.clone()],
546	        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", "100000")],
547	        &cal_trace,
548	    );
549	    if !observer_ran(&cal) {
550	        return;
551	    }
552	    if !trap_armed(&cal_trace) {
553	        eprintln!("skipping: randtrap seccomp trap did not arm here");
554	        return;
555	    }
556	    assert_eq!(cal.rc, 0, "calibration run must succeed");
557	    let fill_base = key_fill_base(&getrandom_events(&cal_trace));
558	    let fail_after = fill_base + TARGET_FRAGMENT;
559	
560	    let fail_after_env = fail_after.to_string();
561	    let obs = observe(
562	        &sup.observer,
563	        bin,
564	        "randfail",
565	        &key,
566	        &[sup.randtrap.clone()],
567	        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", fail_after_env.as_str())],
568	        &trace,
569	    );
570	    if !observer_ran(&obs) {
571	        return;
572	    }
573	    assert!(trap_armed(&trace), "fault run must have the trap armed");
574	    assert_eq!(
575	        obs.rc, 0,
576	        "[{profile}] observer must confirm the wipe, got FAIL: {:?}",
577	        obs.fail.clone()
578	    );
579	
580	    // The scenario really delivered a strict prefix of the key and then
581	    // failed the draw -- corroborated both by the observer and by the
582	    // shim's own trace.
583	    let rf = obs.first("RANDOM_FAILED").expect("RANDOM_FAILED event");
584	    let held = rf.usize("held").expect("held=");
585	    let sentinel = rf.usize("sentinel").expect("sentinel=");
586	    assert!(held > 0 && held < KEY_LEN, "fragment must be 1..31 bytes");
587	    assert_eq!(
588	        held, TARGET_FRAGMENT,
589	        "calibrated cutoff must land {TARGET_FRAGMENT} bytes into the fill"
590	    );
591	    assert_eq!(sentinel, KEY_LEN - held);
592	
593	    // The shim trace independently shows a strict partial delivery followed
594	    // by an unrecoverable error inside the key fill.
595	    let trace_events = getrandom_events(&trace);
596	    let fill_start = trace_events
597	        .iter()
598	        .rposition(|e| e.req == KEY_LEN)
599	        .expect("fault trace must contain the 32-byte fill request");
600	    let fill_calls = &trace_events[fill_start..];
601	    let traced_held: usize = fill_calls.iter().filter(|e| e.ret > 0).map(|e| e.ret as usize).sum();
602	    assert!(
603	        traced_held > 0 && traced_held < KEY_LEN,
604	        "trace must show a strict partial fill, got {traced_held} bytes"
605	    );
606	    assert_eq!(traced_held, held, "observer and trace agree on fragment size");
607	    assert!(
608	        fill_calls.iter().any(|e| e.ret < 0),
609	        "the fill must have ended with an injected failure"
610	    );
611	
612	    // The wipe covers the delivered fragment *and* the never-delivered
613	    // tail (proven by the planted sentinel being erased), before the error
614	    // report and before the operation returned.
615	    let wiped = obs.first("WIPED").expect("WIPED event");
616	    assert_eq!(wiped.usize("held"), Some(held));
617	    assert_eq!(wiped.usize("sentinel"), Some(sentinel));
618	    let i_wiped = obs.index("WIPED").unwrap();
619	    let i_output = obs
620	        .index("OUTPUT_AFTER_WIPE")
621	        .expect("the error report must be observed after the wipe");
622	    assert!(i_wiped < i_output, "wipe must precede the failure report");
623	    assert_eq!(
624	        obs.first("GUEST_EXIT").and_then(|e| e.i64("rc")),
625	        Some(1)
626	    );
627	
628	    // Public failure behavior: no key file, no zero-padded stand-in,
629	    // exit 1, empty stdout, stderr explains the random-source failure and
630	    // names nothing secret; existing files and the parent are untouched.
631	    assert!(!key.exists(), "no key file may be created on a partial draw");
632	    let (out, err) = guest_captured(&key);
633	    assert!(out.is_empty(), "stdout must be empty on failure");
634	    let err_text = String::from_utf8_lossy(&err);
635	    assert!(
636	        err_text.contains("cryptographic random source unavailable"),
637	        "stderr must explain the random-source failure: {err_text}"
638	    );
639	    // The delivered fragment must not appear in the report, raw or hex.
640	    let events = getrandom_events(&trace);
641	    let drawn: Vec<u8> = events
642	        .iter()
643	        .rposition(|e| e.req == KEY_LEN)
644	        .map(|s| {
645	            events[s..]
646	                .iter()
647	                .filter(|e| e.ret > 0)
648	                .flat_map(|e| (0..e.ret as usize).map(move |i| pattern_byte(e.base + i)))
649	                .collect()
650	        })
651	        .unwrap_or_default();
652	    assert_eq!(drawn.len(), held);
653	    assert!(
654	        !contains_slice(&out, &drawn) && !contains_slice(&err, &drawn),
655	        "the delivered fragment must never appear raw on stdout/stderr"
656	    );
657	    let hex: String = drawn.iter().map(|b| format!("{b:02x}")).collect();
658	    assert!(!err_text.contains(&hex), "fragment must not appear hex-encoded");
659	
660	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
661	    assert_eq!(mode_of(&tmp.path), parent_before, "parent mode must survive");
662	}
663	
664	fn write_failure_after_full_key_still_wipes_the_full_key(
665	    sup: &Support,
666	    bin: &Path,
667	    profile: &str,
668	) {
669	    let tmp = Tmp::new(&format!("writefail-{profile}"));
670	    let key = tmp.child("key");
671	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
672	    let parent_before = mode_of(&tmp.path);
673	    let trace = tmp.child("trace.log");
674	    fs::File::create(&trace).unwrap();
675	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
676	
677	    // Deterministic full key, then the permfail shim accepts only 4 bytes
678	    // per write and fails with EIO once 10 bytes have landed: part of the
679	    // key is on disk, the save aborts, the file is unlinked.
680	    let obs = observe(
681	        &sup.observer,
682	        bin,
683	        "writefail",
684	        &key,
685	        &[sup.randtrap.clone(), sup.permfail.clone()],
686	        &[
687	            ("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8"),
688	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
689	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
690	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
691	        ],
692	        &trace,
693	    );
694	    if !observer_ran(&obs) {
695	        return;
696	    }
697	    if !trap_armed(&trace) {
698	        eprintln!("skipping: randtrap seccomp trap did not arm here");
699	        return;
700	    }
701	    assert_eq!(
702	        obs.rc, 0,
703	        "[{profile}] observer must confirm the wipe, got FAIL: {:?}",
704	        obs.fail.clone()
705	    );
706	
707	    // The full, non-zero key was delivered and still held live across the
708	    // key writes, the abort's unlink, and the abort's close.
709	    let secret = obs.secret();
710	    assert_eq!(secret.len(), KEY_LEN);
711	    assert!(secret.iter().all(|&b| b != 0));
712	    assert!(!obs.named("WRITE_BORROWS").is_empty());
713	    assert!(obs.first("WRITE_FAILED").is_some(), "abort unlink must see the full key");
714	    assert!(obs.first("ABORT_UNLINK").is_some());
715	    assert!(obs.first("ABORT_CLOSE_STILL_HELD").is_some());
716	
717	    // The whole full key was wiped before the error report / return.
718	    let i_wiped = obs.index("WIPED").expect("WIPED event");
719	    let wiped = obs.first("WIPED").unwrap();
720	    assert_eq!(wiped.usize("held"), Some(KEY_LEN));
721	    assert_eq!(wiped.usize("sentinel"), Some(0));
722	    assert!(
723	        obs.index("ABORT_CLOSE_STILL_HELD").unwrap() < i_wiped,
724	        "wipe must follow the abort close"
725	    );
726	    assert!(
727	        i_wiped < obs.index("OUTPUT_AFTER_WIPE").unwrap(),
728	        "wipe must precede the failure report"
729	    );
730	    assert_eq!(
731	        obs.first("GUEST_EXIT").and_then(|e| e.i64("rc")),
732	        Some(1)
733	    );
734	
735	    // Public failure behavior: no leftover file, exit 1, empty stdout,
736	    // stderr names the write failure and the target path.
737	    assert!(!key.exists(), "the aborted file must be cleaned up");
738	    let (out, err) = guest_captured(&key);
739	    assert!(out.is_empty(), "no success message on failure");
740	    let err_text = String::from_utf8_lossy(&err);
741	    assert!(
742	        err_text.contains("could not write key file"),
743	        "stderr must explain the write failure: {err_text}"
744	    );
745	    assert!(
746	        err_text.contains(&key.display().to_string()),
747	        "stderr must name the target: {err_text}"
748	    );
749	    // The full key must not leak, raw or hex.
750	    assert!(
751	        !err.windows(KEY_LEN).any(|w| w == secret.as_slice()),
752	        "full key must not appear raw on stderr"
753	    );
754	    let hex: String = secret.iter().map(|b| format!("{b:02x}")).collect();
755	    assert!(!err_text.contains(&hex), "full key must not appear hex-encoded");
756	
757	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
758	    assert_eq!(mode_of(&tmp.path), parent_before, "parent mode must survive");
759	}
760	
761	
762	// ---------------------------------------------------------------------------
763	// tests: each scenario under both build profiles
764	// ---------------------------------------------------------------------------
765	
766	#[test]
767	fn success_zeroes_the_held_key_before_returning_under_both_profiles() {
768	    let Some(sup) = support() else {
769	        eprintln!("skipping: keylife/randtrap/permfail support unavailable");
770	        return;
771	    };
772	    success_wipes_full_key_and_saves_it_intact(&sup, &debug_bin(), "debug");
773	    if let Some(rel) = release_bin() {
774	        success_wipes_full_key_and_saves_it_intact(&sup, &rel, "release");
775	    }
776	}
777	
778	#[test]
779	fn partial_random_failure_zeroes_fragment_and_whole_buffer_under_both_profiles() {
780	    let Some(sup) = support() else {
781	        eprintln!("skipping: keylife/randtrap/permfail support unavailable");
782	        return;
783	    };
784	    partial_random_failure_wipes_fragment_and_entire_buffer(&sup, &debug_bin(), "debug");
785	    if let Some(rel) = release_bin() {
786	        partial_random_failure_wipes_fragment_and_entire_buffer(&sup, &rel, "release");
787	    }
788	}
789	
790	#[test]
791	fn write_failure_after_full_key_zeroes_before_returning_under_both_profiles() {
792	    let Some(sup) = support() else {
793	        eprintln!("skipping: keylife/randtrap/permfail support unavailable");
794	        return;
795	    };
796	    write_failure_after_full_key_still_wipes_the_full_key(&sup, &debug_bin(), "debug");
797	    if let Some(rel) = release_bin() {
798	        write_failure_after_full_key_still_wipes_the_full_key(&sup, &rel, "release");
799	    }
800	}
