183	
184	struct observer {
185	    pid_t pid;
186	    enum mode mode;
187	
188	    uint64_t p;                 /* address of the guest's 32-byte buffer */
189	    int phase;                  /* 0 pre-fill, 1 filling, 2 filled,
190	                                   4 wipe watch armed, 5 wipe observed */
191	    int held;                   /* pattern prefix delivered so far */
192	    int sentinel;               /* sentinel bytes planted in undelivered tail */
193	    uint8_t secret[KEYN];       /* observed full key (once filled) */
194	    int keyfd;                  /* fd of the key file, or -1 */
195	    int abort_unlink_seen;      /* abort_save's unlink after a failed save */
196	    int output_after_wipe;
197	    int fill_req32_seen;
198	    int wipe_reported;
199	    long wipe_steps;
200	    int failed;
201	    char fail_reason[256];
202	
203	    /* pending syscall-entry state */
204	    int entry_valid;
205	    long entry_nr;
206	    uint64_t entry_a0, entry_a1, entry_a2;
207	};
