217	static void set_fail(struct observer *o, const char *fmt, ...)
218	{
219	    if (o->failed)
220	        return;
221	    va_list ap;
222	    va_start(ap, fmt);
223	    o->failed = 1;
224	    vsnprintf(o->fail_reason, sizeof o->fail_reason, fmt, ap);
225	    va_end(ap);
226	    printf("FAIL reason=%s\n", o->fail_reason);
227	    fflush(stdout);
228	}
