230	/* ---- remote memory ---- */
231	
232	static int remote_read(struct observer *o, uint64_t addr, void *buf, size_t n)
233	{
234	    struct iovec local = { buf, n };
235	    struct iovec remote = { (void *)addr, n };
236	    return process_vm_readv(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
237	               ? 0
238	               : -1;
239	}
240	
241	static int remote_write(struct observer *o, uint64_t addr, const void *buf,
242	                        size_t n)
243	{
244	    struct iovec local = { (void *)buf, n };
245	    struct iovec remote = { (void *)addr, n };
246	    return process_vm_writev(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
247	               ? 0
248	               : -1;
249	}
250	
251	static void get_gregs(struct observer *o, gregs_t *g)
252	{
253	    struct iovec iov = { g, sizeof *g };
254	    if (ptrace(PTRACE_GETREGSET, o->pid, (void *)GREG_NT, &iov) < 0)
255	        set_fail(o, "PTRACE_GETREGSET: %s", strerror(errno));
256	}
257	
258	static int read_keybuf(struct observer *o, uint8_t out[KEYN])
259	{
260	    memset(out, 0, KEYN);
261	    if (!o->p)
262	        return -1;
263	    return remote_read(o, o->p, out, KEYN);
264	}
265	
266	/* ---- the randtrap delivery pattern ---- */
267	
268	static uint8_t pattern_next(uint8_t b)
269	{
270	    return (uint8_t)(0x80 + (((unsigned)b - 0x80u + 1u) % 64u));
271	}
272	
273	/* Length of the contiguous non-zero pattern prefix the random source left:
274	 * starts with a 0x80..0xBF byte, every next byte advances by one modulo
275	 * the pattern period, and an undelivered slot is still zero. */
276	static int pattern_prefix(const uint8_t *buf)
277	{
278	    int i = 0;
279	    if (buf[0] < 0x80 || buf[0] >= 0xc0)
280	        return 0;
281	    while (i < KEYN && buf[i] != 0) {
282	        if (i > 0 && buf[i] != pattern_next(buf[i - 1]))
283	            break;
284	        i++;
285	    }
286	    return i;
287	}
288	
289	static int all_zero(const uint8_t *buf, int n)
290	{
291	    for (int i = 0; i < n; i++)
292	        if (buf[i])
293	            return 0;
294	    return 1;
295	}
296	
297	static void print_hex(const uint8_t *buf, int n)
298	{
299	    for (int i = 0; i < n; i++)
300	        printf("%02x", buf[i]);
301	}
302	
303	/* [P, P+32) must still equal the observed full key while the save borrows
304	 * it: a premature or partial wipe shows up here. */
305	static void require_still_holds_full_key(struct observer *o, const char *what,
306	                                         long fd)
307	{
308	    uint8_t cur[KEYN];
309	    if (read_keybuf(o, cur) != 0) {
310	        set_fail(o, "%s: cannot read key buffer", what);
311	        return;
312	    }
313	    if (memcmp(cur, o->secret, KEYN) != 0) {
314	        set_fail(o, "%s fd=%ld: key buffer changed before the save finished",
315	                 what, fd);
316	        return;
317	    }
318	    printf("EVENT name=%s fd=%ld held=%d\n", what, fd, KEYN);
319	    fflush(stdout);
320	}
321	
322	/* Classify the buffer after a getrandom completion of the key fill. */
323	static void refresh_fill(struct observer *o, long ret)
324	{
325	    uint8_t cur[KEYN];
326	    if (read_keybuf(o, cur) != 0) {
327	        set_fail(o, "cannot read key buffer after getrandom");
328	        return;
329	    }
330	    int pre = pattern_prefix(cur);
331	
332	    if (ret < 0) {
333	        if (o->mode != MODE_RANDFAIL) {
334	            set_fail(o,
335	                     "unexpected getrandom failure (ret=%ld) in mode %d",
336	                     ret, (int)o->mode);
337	            return;
338	        }
339	        if (pre <= 0 || pre >= KEYN) {
340	            set_fail(o,
341	                     "randfail scenario expected a partial delivery "
342	                     "(1..31 bytes), got prefix=%d ret=%ld",
343	                     pre, ret);
344	            return;
345	        }
346	        /* Plant a non-zero sentinel in the slots the source never
347	         * delivered: the product cannot read them on this error path, and
348	         * a full-buffer wipe must erase them as well. Bytes stay outside
349	         * the 0x80..0xBF pattern band so they cannot be mistaken for
350	         * random material. */
351	        uint8_t sent[KEYN];
352	        int m = KEYN - pre;
353	        for (int i = 0; i < m; i++)
354	            sent[i] =
355	                (uint8_t)(0xd0 + ((unsigned)(i * 5 + pre + 1) & 0x0f));
356	        if (remote_write(o, o->p + (uint64_t)pre, sent, (size_t)m) != 0) {
357	            set_fail(o, "cannot plant sentinel in undelivered tail");
358	            return;
359	        }
360	        o->held = pre;
361	        o->sentinel = m;
362	        memcpy(o->secret, cur, KEYN);
363	        o->phase = 4;
364	        o->wipe_steps = 0;
365	        printf("EVENT name=RANDOM_FAILED held=%d sentinel=%d\n", pre, m);
366	        fflush(stdout);
367	        return;
368	    }
369	
370	    o->held = pre;
371	    if (pre == KEYN) {
372	        memcpy(o->secret, cur, KEYN);
373	        o->phase = 2;
374	        printf("EVENT name=FILL_COMPLETE held=32 secret=");
375	        print_hex(cur, KEYN);
376	        putchar('\n');
377	        fflush(stdout);
378	    } else {
379	        o->phase = 1;
380	    }
381	}
382	
383	/* A completion of a getrandom that belongs to keygen's fill. `ret` is what
384	 * the guest observes (kernel return or the emulated SIGSYS value). */
385	static void on_getrandom_done(struct observer *o, long ret)
386	{
387	    if (!o->fill_req32_seen || o->phase >= 2 || o->phase == 4)
388	        return;
389	    refresh_fill(o, ret);
390	}
391	
392	/* ---- syscall-entry/exit handling (normal syscall-stop mode) ---- */
393	
394	static void on_syscall_entry(struct observer *o,
395	                             const struct ptrace_syscall_info *si)
396	{
397	    long nr = (long)si->entry.nr;
398	    o->entry_valid = 1;
399	    o->entry_nr = nr;
400	    o->entry_a0 = (uint64_t)si->entry.args[0];
401	    o->entry_a1 = (uint64_t)si->entry.args[1];
402	    o->entry_a2 = (uint64_t)si->entry.args[2];
403	
404	    if (nr == SYS_getrandom) {
405	        unsigned long len = (unsigned long)si->entry.args[1];
406	        /* The 32-byte request identifies keygen's own draw: the crate's
407	         * zero-length probe and the runtime startup draws use other
408	         * lengths, and the key fill is the process's first/final 32-byte
409	         * run. Once the key is filled a later unrelated 32-byte request
410	         * must never re-point P at a different buffer. */
411	        if (len == KEYN && !o->fill_req32_seen && o->phase < 2) {
412	            o->p = (uint64_t)si->entry.args[0];
413	            o->fill_req32_seen = 1;
414	            o->phase = 1;
415	            o->held = 0;
416	            o->sentinel = 0;
417	            o->wipe_reported = 0;
418	        }
419	        return;
420	    }
421	
422	    if (nr == SYS_write || nr == SYS_writev) {
423	        long fd = (long)si->entry.args[0];
424	        /* After the wipe the first stdout/stderr write confirms ordering. */
425	        if (o->phase == 5 && (fd == 1 || fd == 2)) {
426	            if (!o->output_after_wipe) {
427	                o->output_after_wipe = 1;
428	                printf("EVENT name=OUTPUT_AFTER_WIPE fd=%ld\n", fd);
429	                fflush(stdout);
430	            }
431	        }
432	
433	        /* Identify the key fd by *content*, not by "the first openat after
434	         * the fill": the product saves with plain write(2) of the key
435	         * buffer, so the first write whose offered bytes equal the key's
436	         * prefix can only target the key file. This stays correct even if
437	         * the runtime opens/writes something else between the fill and the
438	         * key file. Short writes advance the pointer, so only the first
439	         * offer (offset 0) is used for identification. */
440	        if (o->phase == 2 && o->keyfd < 0 &&
441	            !(fd == 1 || fd == 2)) {
442	            uint8_t offered[KEYN];
443	            size_t peek = (size_t)si->entry.args[2];
444	            if (peek > KEYN)
445	                peek = KEYN;
446	            if (peek >= 4 &&
447	                remote_read(o, (uint64_t)si->entry.args[1], offered,
448	                            peek) == 0 &&
449	                memcmp(offered, o->secret, peek) == 0) {
450	                o->keyfd = (int)fd;
451	            }
452	        }
453	
454	        /* Every offer of key bytes to the key fd must borrow the still-live
455	         * full key (checked at the buffer's own address, not the offer
456	         * pointer, so short writes with advancing pointers are covered). */
457	        if (o->phase >= 2 && o->keyfd >= 0 && fd == (long)o->keyfd)
458	            require_still_holds_full_key(o, "WRITE_BORROWS", fd);
459	    }
460	
461	    if (nr == SYS_unlinkat) {
462	        /* writefail mode: the failed save (the permfail shim makes the libc
463	         * write() return EIO without a syscall, so the failure itself is
464	         * not a syscall-exit event) reaches abort_save, whose first step is
465	         * unlinking this invocation's file. At that moment the complete key
466	         * must still be in the buffer: the wipe is only allowed afterwards,
467	         * on the way out of the operation. */
468	        if (o->mode == MODE_WRITEFAIL && o->phase == 2 &&
469	            o->keyfd >= 0 && !o->abort_unlink_seen) {
470	            require_still_holds_full_key(o, "WRITE_FAILED", (long)o->keyfd);
471	            if (!o->failed) {
472	                o->abort_unlink_seen = 1;
473	                printf("EVENT name=ABORT_UNLINK fd=%d held=%d\n", o->keyfd,
474	                       KEYN);
475	                fflush(stdout);
476	            }
477	        }
478	    }
479	}
480	
481	static void on_syscall_exit(struct observer *o,
482	                            const struct ptrace_syscall_info *si)
483	{
484	    long rval = (long)si->exit.rval;
485	    int iserr = si->exit.is_error;
486	
487	    if (!o->entry_valid)
488	        return;
489	
490	    switch (o->entry_nr) {
491	    case SYS_getrandom:
492	        on_getrandom_done(o, rval);
493	        break;
494	
495	    case SYS_openat:
496	        /* The key fd is identified by the content of the first key write
497	         * (see on_syscall_entry), not by fd number, so openat needs no
498	         * tracking here. */
499	        break;
500	
501	    case SYS_write:
502	    case SYS_writev:
503	        /* The write failure itself is injected inside libc by the permfail
504	         * shim (it returns EIO without issuing the syscall), so it is
505	         * recognized at abort_save's unlink entry, not here. */
506	        break;
507	
508	    case SYS_close:
509	        if (o->phase == 2 && o->keyfd >= 0 &&
510	            (long)o->entry_a0 == (long)o->keyfd && !iserr) {
511	            if (o->mode == MODE_SUCCESS) {
512	                require_still_holds_full_key(o, "CLOSE_STILL_HELD",
513	                                            (long)o->keyfd);
514	            } else if (o->mode == MODE_WRITEFAIL && o->abort_unlink_seen) {
515	                /* abort_save unlinked first and now closes the still-open
516	                 * key fd; the full key must still be present at this point
517	                 * and wiped only afterwards, on the way out. */
518	                require_still_holds_full_key(o, "ABORT_CLOSE_STILL_HELD",
519	                                            (long)o->keyfd);
520	            }
521	            if (!o->failed &&
522	                ((o->mode == MODE_SUCCESS) ||
523	                 (o->mode == MODE_WRITEFAIL && o->abort_unlink_seen))) {
524	                o->phase = 4;
525	                o->held = KEYN;
526	                o->sentinel = 0;
527	                o->wipe_steps = 0;
528	            }
529	        }
530	        break;
531	    }
532	
533	    o->entry_valid = 0;
534	}
535	
536	/* ---- SIGSYS (seccomp-emulated getrandom) handling ---- */
537	
538	/* The randtrap shim emulates a trapped getrandom inside a SIGSYS handler:
539	 * delivery stop -> handler runs (its own trace write) -> rt_sigreturn ->
540	 * the guest resumes after the svc with the emulated value in the return
541	 * register. Drive that sequence and hand the emulated result to the fill
542	 * tracker. Returns 0 normally, -1 once the guest is gone or a FAIL was
543	 * raised. */
544	static int drive_sigsys(struct observer *o)
545	{
546	    int status;
547	    int delivered = 0;
548	    for (;;) {
549	        /* Inject SIGSYS exactly once: re-injecting on every stop would
550	         * queue additional SIGSYSs behind the handler's blocked signal,
551	         * and sigreturn unblocking it would re-enter the handler forever. */
552	        if (ptrace(PTRACE_SYSCALL, o->pid, 0,
553	                   delivered ? 0 : (void *)(long)SIGSYS) < 0) {
554	            set_fail(o, "ptrace inject SIGSYS: %s", strerror(errno));
555	            return -1;
556	        }
557	        delivered = 1;
558	        if (waitpid(o->pid, &status, 0) < 0) {
559	            set_fail(o, "waitpid in SIGSYS: %s", strerror(errno));
560	            return -1;
561	        }
562	        if (WIFEXITED(status) || WIFSIGNALED(status))
563	            return -1;
564	        if (!WIFSTOPPED(status))
565	            continue;
566	        int sig = WSTOPSIG(status);
567	        if (sig == (SIGTRAP | 0x80)) {
568	            struct ptrace_syscall_info si;
569	            memset(&si, 0, sizeof si);
570	            if (ptrace(PTRACE_GET_SYSCALL_INFO, o->pid, sizeof si, &si) < 0)
571	                continue;
572	            if (si.op == PTRACE_SYSCALL_INFO_ENTRY &&
573	                (long)si.entry.nr == SYS_rt_sigreturn_local) {
574	                /* Run rt_sigreturn; on its exit the restored frame carries
575	                 * the emulated getrandom result. */
576	                if (ptrace(PTRACE_SYSCALL, o->pid, 0, 0) < 0)
577	                    return -1;
578	                if (waitpid(o->pid, &status, 0) < 0)
579	                    return -1;
580	                if (WIFEXITED(status) || WIFSIGNALED(status))
581	                    return -1;
582	                gregs_t g;
583	                get_gregs(o, &g);
584	                if (o->failed)
585	                    return -1;
586	                on_getrandom_done(o, greg_ret(&g));
587	                return o->failed ? -1 : 0;
588	            }
589	        } else if (sig == SIGSYS) {
590	            /* A second SIGSYS stop before the handler ran (nested trap
591	             * bookkeeping): it is already being delivered; resume with no
592	             * new injection. */
593	            delivered = 1;
594	            continue;
595	        }
596	    }
597	}
598	
599	/* ---- wipe watch (single-step mode) ---- */
600	
601	/* If the guest is stopped immediately before a write/exit_group syscall
602	 * (entry syscall-stop, or a single-step trap on the syscall instruction),
603	 * return its number and fd argument; otherwise -1. */
604	static long pending_syscall(struct observer *o, int sig,
605	                            const struct ptrace_syscall_info *si,
606	                            const gregs_t *g, long *fd_out)
607	{
608	    if (sig == (SIGTRAP | 0x80) && si->op == PTRACE_SYSCALL_INFO_ENTRY) {
609	        long nr = (long)si->entry.nr;
610	        *fd_out = (long)si->entry.args[0];
611	        return nr;
612	    }
613	    if (sig == SIGTRAP) {
614	        unsigned long pc = greg_pc(g);
615	        uint32_t insn = 0;
616	        if (remote_read(o, pc, &insn, sizeof insn) == 0 &&
617	            is_syscall_insn_word(insn)) {
618	            long nr = greg_nr(g);
619	            *fd_out = greg_arg(g, 0);
620	            return nr;
621	        }
622	    }
623	    return -1;
624	}
625	
626	/* One single-step observation. Returns 1 while the watch stays armed. */
627	static int watch_step(struct observer *o, int sig,
628	                      const struct ptrace_syscall_info *si, const gregs_t *g)
629	{
630	    o->wipe_steps++;
631	    if (o->wipe_steps > WIPE_STEP_BUDGET) {
632	        set_fail(o,
633	                 "key buffer was not zeroed within %ld user instructions",
634	                 WIPE_STEP_BUDGET);
635	        return 0;
636	    }
637	
638	    uint8_t cur[KEYN];
639	    if (read_keybuf(o, cur) != 0) {
640	        set_fail(o, "cannot read key buffer while wipe-watching");
641	        return 0;
642	    }
643	
644	    long fd = -1;
645	    long nr = pending_syscall(o, sig, si, g, &fd);
646	    if ((nr == SYS_write || nr == SYS_writev) && (fd == 1 || fd == 2)) {
647	        if (!all_zero(cur, KEYN)) {
648	            set_fail(o,
649	                     "guest performed fd %ld output before the key buffer "
650	                     "was zeroed (held=%d sentinel=%d, step %ld)",
651	                     fd, o->held, o->sentinel, o->wipe_steps);
652	            return 0;
653	        }
654	        if (!o->output_after_wipe) {
655	            o->output_after_wipe = 1;
656	            printf("EVENT name=OUTPUT_AFTER_WIPE fd=%ld\n", fd);
657	            fflush(stdout);
658	        }
659	    }
660	    if (nr == SYS_exit_group && !all_zero(cur, KEYN)) {
661	        set_fail(o,
662	                 "guest reached exit_group with the key buffer not zeroed "
663	                 "(held=%d sentinel=%d)",
664	                 o->held, o->sentinel);
665	        return 0;
666	    }
667	
668	    if (!o->wipe_reported && all_zero(cur, KEYN)) {
669	        o->wipe_reported = 1;
670	        o->phase = 5;
671	        printf("EVENT name=WIPED held=%d sentinel=%d steps=%ld\n", o->held,
672	               o->sentinel, o->wipe_steps);
673	        fflush(stdout);
674	        return 0;
675	    }
676	    return 1;
677	}
678	
679	/* ---- child ---- */
680	
681	static void run_child(char **argv, const char *out_cap, const char *err_cap)
682	{
683	    int outfd = open(out_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
684	    if (outfd < 0)
685	        _exit(126);
686	    int errfd = open(err_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
687	    if (errfd < 0)
688	        _exit(126);
689	    dup2(outfd, STDOUT_FILENO);
690	    dup2(errfd, STDERR_FILENO);
691	    if (outfd > STDERR_FILENO)
692	        close(outfd);
693	    if (errfd > STDERR_FILENO)
694	        close(errfd);
695	
696	    ptrace(PTRACE_TRACEME, 0, 0, 0);
697	    raise(SIGSTOP);
698	    execv(argv[0], argv);
699	    _exit(127);
700	}
701	
702	int main(int argc, char **argv)
703	{
704	    if (argc < 6)
705	        die_usage();
706	    enum mode mode;
707	    if (!strcmp(argv[1], "success"))
708	        mode = MODE_SUCCESS;
709	    else if (!strcmp(argv[1], "randfail"))
710	        mode = MODE_RANDFAIL;
711	    else if (!strcmp(argv[1], "writefail"))
712	        mode = MODE_WRITEFAIL;
713	    else
714	        die_usage();
715	    const char *out_cap = argv[2];
716	    const char *err_cap = argv[3];
717	    if (strcmp(argv[4], "--") != 0)
718	        die_usage();
719	    char **guest_argv = &argv[5];
720	
721	    struct observer o;
722	    memset(&o, 0, sizeof o);
723	    o.mode = mode;
724	    o.keyfd = -1;
725	
726	    pid_t pid = fork();
727	    if (pid < 0) {
728	        perror("fork");
729	        return 2;
730	    }
731	    if (pid == 0)
732	        run_child(guest_argv, out_cap, err_cap);
733	    o.pid = pid;
734	
735	    int status;
736	    if (waitpid(pid, &status, WUNTRACED) < 0) {
737	        perror("waitpid initial");
738	        kill(pid, SIGKILL);
739	        waitpid(pid, &status, 0);
740	        return 2;
741	    }
742	    if (WIFEXITED(status) || WIFSIGNALED(status)) {
743	        fprintf(stderr, "guest exited before tracing could start\n");
744	        return 2;
745	    }
746	    /* TRACEEXEC makes the post-exec stop a proper PTRACE_EVENT stop (plain
747	     * SIGTRAP with the event marker in the wait status) instead of a legacy
748	     * SIGTRAP that looks like a signal to deliver -- delivering that would
749	     * kill the guest at the very first stop. */
750	    if (ptrace(PTRACE_SETOPTIONS, pid, 0,
751	               (void *)(long)(PTRACE_O_TRACESYSGOOD | PTRACE_O_TRACEEXEC)) < 0) {
752	        fprintf(stderr, "PTRACE_SETOPTIONS: %s\n", strerror(errno));
753	        kill(pid, SIGKILL);
754	        waitpid(pid, &status, 0);
755	        return 2;
756	    }
757	
758	    int stepping = 0;
759	    int guest_rc = -1;
760	    int inject_sig = 0;
761	    for (;;) {
762	        long request = stepping ? PTRACE_SINGLESTEP : PTRACE_SYSCALL;
763	        if (ptrace(request, pid, 0,
764	                   inject_sig ? (void *)(long)inject_sig : 0) < 0) {
765	            if (errno == ESRCH)
766	                break;
767	            set_fail(&o, "ptrace continue: %s", strerror(errno));
768	            break;
769	        }
770	        inject_sig = 0;
771	        if (waitpid(pid, &status, 0) < 0) {
772	            set_fail(&o, "waitpid: %s", strerror(errno));
773	            break;
774	        }
775	        if (WIFEXITED(status)) {
776	            guest_rc = WEXITSTATUS(status);
777	            printf("EVENT name=GUEST_EXIT rc=%d\n", guest_rc);
778	            fflush(stdout);
779	            break;
780	        }
781	        if (WIFSIGNALED(status)) {
782	            set_fail(&o, "guest killed by signal %d", WTERMSIG(status));
783	            break;
784	        }
785	        if (!WIFSTOPPED(status)) {
786	            set_fail(&o, "unexpected wait status 0x%x", status);
787	            break;
788	        }
789	        int sig = WSTOPSIG(status);
790	        unsigned int event = (unsigned int)((unsigned)status >> 16);
791	
792	        /* A seccomp-trapped getrandom has no ordinary entry/exit pair:
793	         * drive the SIGSYS handler before doing anything else. */
794	        if (sig == SIGSYS) {
795	            if (drive_sigsys(&o) < 0)
796	                break;
797	            if (o.phase == 4 && !o.failed)
798	                stepping = 1;
799	            continue;
800	        }
801	
802	        /* PTRACE_EVENT stops (e.g. PTRACE_EVENT_EXEC after the child's
803	         * execve) are bookkeeping, not signals: continue silently. */
804	        if (sig == SIGTRAP && event != 0)
805	            continue;
806	
807	        gregs_t g;
808	        struct ptrace_syscall_info si;
809	        memset(&si, 0, sizeof si);
810	        if (sig == (SIGTRAP | 0x80))
811	            (void)ptrace(PTRACE_GET_SYSCALL_INFO, pid, sizeof si, &si);
812	        get_gregs(&o, &g);
813	        if (o.failed)
814	            break;
815	
816	        if (stepping) {
817	            /* Inside the watch window a plain SIGTRAP (no event marker, no
818	             * syscall-good bit) is the single-step trap; a syscall-good
819	             * stop is stepping over a syscall instruction. Anything else is
820	             * a genuine signal to reinject. */
821	            if (sig != SIGTRAP && sig != (SIGTRAP | 0x80)) {
822	                inject_sig = sig;
823	                continue;
824	            }
825	            if (!watch_step(&o, sig, &si, &g))
826	                stepping = 0;
827	            continue;
828	        }
829	
830	        if (sig != (SIGTRAP | 0x80)) {
831	            /* Genuine signal: deliver it to the guest and keep tracing. */
832	            inject_sig = sig;
833	            continue;
834	        }
835	
836	        if (si.op == PTRACE_SYSCALL_INFO_ENTRY)
837	            on_syscall_entry(&o, &si);
838	        else if (si.op == PTRACE_SYSCALL_INFO_EXIT)
839	            on_syscall_exit(&o, &si);
840	        if (o.failed)
841	            break;
842	        if (o.phase == 4)
843	            stepping = 1;
844	    }
845	
846	    if (!o.failed) {
847	        if (o.phase != 5) {
848	            set_fail(&o,
849	                     "wipe was never observed (phase=%d held=%d sentinel=%d)",
850	                     o.phase, o.held, o.sentinel);
851	        } else if (!o.output_after_wipe) {
852	            set_fail(&o,
853	                     "buffer was wiped but the program then made no "
854	                     "stdout/stderr write to confirm ordering");
855	        } else if (mode == MODE_SUCCESS && o.keyfd < 0) {
856	            set_fail(&o, "success path never opened the key file");
857	        } else if (mode == MODE_RANDFAIL && o.sentinel == 0) {
858	            set_fail(&o, "randfail path never planted the tail sentinel");
859	        } else if (mode == MODE_WRITEFAIL && o.keyfd < 0) {
860	            set_fail(&o, "writefail path never opened the key file");
861	        }
862	    }
863	
864	    if (o.failed) {
865	        kill(pid, SIGKILL);
866	        waitpid(pid, &status, 0);
867	    }
868	
869	    (void)guest_rc;
870	    return o.failed ? 1 : 0;
871	}
