117	static int cfg_lie_mode    = -1; /* -1 = disabled */
118	static long cfg_partial_write = 0;      /* 0 = disabled */
119	static int  cfg_write_eintr = 0;        /* first N write() calls fail EINTR */
120	static long cfg_fail_write_after = -1;  /* -1 = disabled */
121	static long cfg_write_zero_after = -1;  /* -1 = disabled */
122	static int  cfg_fail_fsync = 0;
