135	/* ----- activation: only inside the wrapfile executable ----- */
136	
137	static int process_active(void)
138	{
139	    static int cached = -1;
140	    if (cached != -1)
141	        return cached;
142	
143	    char buf[512];
144	    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
145	    if (n <= 0) {
146	        cached = 0;
147	        return 0;
148	    }
149	    buf[n] = '\0';
150	    const char *base = strrchr(buf, '/');
151	    base = base ? base + 1 : buf;
152	    cached = (strncmp(base, "wrapfile", 8) == 0) ? 1 : 0;
153	    return cached;
154	}
