169	        (void)v; /* opened lazily on first trace() */
170	    if ((v = getenv("WRAPFILE_TEST_LIE_MODE")) && v[0] != '\0')
171	        cfg_lie_mode = (int)strtol(v, NULL, 8);
172	    if ((v = getenv("WRAPFILE_TEST_PARTIAL_WRITE")) && v[0] != '\0')
173	        cfg_partial_write = strtol(v, NULL, 10);
174	    if ((v = getenv("WRAPFILE_TEST_WRITE_EINTR")) && v[0] != '\0')
175	        cfg_write_eintr = atoi(v);
