177	        cfg_fail_write_after = strtol(v, NULL, 10);
178	    if ((v = getenv("WRAPFILE_TEST_WRITE_ZERO_AFTER")) && v[0] != '\0')
179	        cfg_write_zero_after = strtol(v, NULL, 10);
180	    if ((v = getenv("WRAPFILE_TEST_FAIL_FSYNC")) && v[0] == '1')
