191	
192	static int trace_fd(void)
193	{
194	    static int fd = -2; /* -2 = not initialised */
195	    if (fd != -2)
196	        return fd;
197	
198	    const char *path = getenv("WRAPFILE_TEST_TRACE_FILE");
199	    if (!path || !path[0]) {
200	        fd = -1;
201	        return fd;
202	    }
203	    /*
204	     * Raw openat(AT_FDCWD, ...) syscall rather than open(): going through
205	     * our own open() wrapper inside the wrapfile process would mark the
206	     * trace file as a tracked, created descriptor and mis-attribute writes
207	     * to it. The syscall bypasses all libc interposition.
208	     */
209	    fd = (int)syscall(SYS_openat, AT_FDCWD, path,
210	                      O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
211	    return fd;
212	}
