225	/* ----- per-descriptor helpers ----- */
226	
227	static fstat_fn get_real_fstat(void)
228	{
229	    if (!real_fstat)
230	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
231	    return real_fstat;
