239	/* malloc'd lowercase hex of n bytes, or NULL. Caller frees. */
240	static char *hex_encode(const unsigned char *p, size_t n)
241	{
242	    static const char digits[] = "0123456789abcdef";
243	    char *hex = malloc(n * 2 + 1);
244	    if (!hex)
245	        return NULL;
246	    for (size_t i = 0; i < n; i++) {
247	        hex[i * 2] = digits[p[i] >> 4];
248	        hex[i * 2 + 1] = digits[p[i] & 0xf];
249	    }
250	    hex[n * 2] = '\0';
251	    return hex;
252	}
