254	static void note_created(int fd)
255	{
256	    if (fd < 0 || fd >= FD_MAX)
257	        return;
258	    tracked[fd] = 1;
259	    written[fd] = 0;
260	    eintr_left[fd] = (cfg_write_eintr > 0 && cfg_write_eintr < 256)
261	                         ? (unsigned char)cfg_write_eintr
262	                         : 0;
263	    written_total[fd] = 0;
