265	    struct stat st;
266	    fstat_fn fn = get_real_fstat();
267	    if (fn && fn(fd, &st) == 0) {
268	        trace("BORN fd=%d mode=0%04o\n", fd,
269	              (unsigned)(st.st_mode & 07777));
