273	/*
274	 * Shared fstat handling for tracked fds: perform the real fstat (via the
275	 * passed function), apply fault/lie policy, log the result, and tell the
276	 * caller what to return.
277	 */
278	static int handle_fstat(int fd, void *st, int is64)
279	{
280	    int rc = is64 ? real_fstat64(fd, (struct stat64 *)st)
281	                  : real_fstat(fd, (struct stat *)st);
282	
283	    if (!is_tracked(fd))
284	        return rc;
285	
286	    if (rc != 0) {
287	        trace("FSTAT ret=-1 mode=00000 size=0\n");
288	        return rc;
289	    }
290	
291	    mode_t real_mode;
292	    off_t real_size;
293	    if (is64) {
294	        struct stat64 *s = (struct stat64 *)st;
295	        real_mode = s->st_mode;
296	        real_size = s->st_size;
297	    } else {
298	        struct stat *s = (struct stat *)st;
299	        real_mode = s->st_mode;
300	        real_size = s->st_size;
301	    }
302	
303	    if (cfg_fail_fstat) {
304	        trace("FSTAT ret=-1 mode=0%04o size=%lld\n",
305	              (unsigned)(real_mode & 07777), (long long)real_size);
306	        errno = EBADF;
307	        return -1;
308	    }
309	
310	    mode_t reported = real_mode;
311	    if (cfg_lie_mode >= 0) {
312	        reported = (real_mode & ~(mode_t)07777) | (mode_t)cfg_lie_mode;
313	        if (is64)
314	            ((struct stat64 *)st)->st_mode = reported;
315	        else
316	            ((struct stat *)st)->st_mode = reported;
317	    }
318	
319	    trace("FSTAT ret=0 mode=0%04o size=%lld\n",
320	          (unsigned)(reported & 07777), (long long)real_size);
321	    return 0;
322	}
323	
324	/* ----- intercepted libc functions ----- */
325	
326	int open(const char *path, int flags, ...)
327	{
328	    if (!real_open)
329	        real_open = (open_fn)dlsym(RTLD_NEXT, "open");
330	
331	    mode_t mode = 0;
332	    if (flags & O_CREAT) {
333	        va_list ap;
334	        va_start(ap, flags);
335	        mode = va_arg(ap, mode_t);
336	        va_end(ap);
337	    }
338	
339	    int fd = real_open(path, flags, mode);
340	
341	    if (process_active() && (flags & O_CREAT)) {
342	        load_config();
343	        if (fd >= 0)
344	            note_created(fd);
345	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
346	              (unsigned)(mode & 07777));
347	    }
348	    return fd;
349	}
350	
351	int open64(const char *path, int flags, ...)
352	{
353	    if (!real_open64)
354	        real_open64 = (open64_fn)dlsym(RTLD_NEXT, "open64");
355	
356	    mode_t mode = 0;
357	    if (flags & O_CREAT) {
358	        va_list ap;
359	        va_start(ap, flags);
360	        mode = va_arg(ap, mode_t);
361	        va_end(ap);
362	    }
363	
364	    int fd = real_open64(path, flags, mode);
365	
366	    if (process_active() && (flags & O_CREAT)) {
367	        load_config();
368	        if (fd >= 0)
369	            note_created(fd);
370	        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
371	              (unsigned)(mode & 07777));
372	    }
373	    return fd;
374	}
375	
376	int fchmod(int fd, mode_t mode)
377	{
378	    if (!real_fchmod)
379	        real_fchmod = (fchmod_fn)dlsym(RTLD_NEXT, "fchmod");
380	
381	    if (!process_active())
382	        return real_fchmod(fd, mode);
383	    load_config();
384	
385	    if (is_tracked(fd) && cfg_fail_fchmod) {
386	        trace("FCHMOD ret=-1 mode=0%04o\n", (unsigned)(mode & 07777));
387	        errno = EPERM;
388	        return -1;
389	    }
390	
391	    int rc = real_fchmod(fd, mode);
392	    if (is_tracked(fd)) {
393	        trace("FCHMOD ret=%d mode=0%04o\n", rc,
394	              (unsigned)(mode & 07777));
395	    }
396	    return rc;
397	}
398	
399	int fstat(int fd, struct stat *st)
400	{
401	    if (!real_fstat)
402	        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
403	    if (!process_active())
404	        return real_fstat(fd, st);
405	    load_config();
406	    if (!is_tracked(fd))
407	        return real_fstat(fd, st);
408	    return handle_fstat(fd, st, 0);
409	}
410	
411	int fstat64(int fd, struct stat64 *st)
412	{
413	    if (!real_fstat64)
414	        real_fstat64 = (fstat64_fn)dlsym(RTLD_NEXT, "fstat64");
415	    if (!process_active())
416	        return real_fstat64(fd, st);
417	    load_config();
418	    if (!is_tracked(fd))
419	        return real_fstat64(fd, st);
420	    return handle_fstat(fd, st, 1);
421	}
422	
423	ssize_t write(int fd, const void *buf, size_t count)
424	{
425	    if (!real_write)
426	        real_write = (write_fn)dlsym(RTLD_NEXT, "write");
427	
428	    if (!process_active() || !is_tracked(fd))
429	        return real_write(fd, buf, count);
430	    load_config();
431	
432	    if (!written[fd]) {
433	        written[fd] = 1;
434	        struct stat st;
435	        fstat_fn fn = get_real_fstat();
436	        if (fn && fn(fd, &st) == 0) {
437	            trace("FIRST_WRITE mode=0%04o size=%lld\n",
438	                  (unsigned)(st.st_mode & 07777),
439	                  (long long)st.st_size);
440	        } else {
441	            trace("FIRST_WRITE mode=unknown size=unknown\n");
442	        }
443	    }
444	
445	    /* A recoverable interruption: the call fails before any byte is
446	     * consumed, and the next call succeeds. */
447	    if (eintr_left[fd] > 0) {
448	        eintr_left[fd]--;
449	        trace("WRITE ret=-1 errno=EINTR\n");
450	        errno = EINTR;
451	        return -1;
452	    }
453	
454	    /* A kernel that only accepts part of the buffer per call. */
455	    size_t allowed = count;
456	    if (cfg_partial_write > 0 && allowed > (size_t)cfg_partial_write)
457	        allowed = (size_t)cfg_partial_write;
458	
459	    /* An unrecoverable error once N bytes have landed. */
460	    if (cfg_fail_write_after >= 0) {
461	        long long remaining =
462	            (long long)cfg_fail_write_after - (long long)written_total[fd];
463	        if (remaining <= 0) {
464	            trace("WRITE ret=-1 errno=EIO off=%llu\n", written_total[fd]);
465	            errno = EIO;
466	            return -1;
467	        }
468	        if (allowed > (size_t)remaining)
469	            allowed = (size_t)remaining;
470	    }
471	
472	    /* No progress and no error: once N bytes have landed, write() accepts
473	     * 0 bytes and reports success-with-zero -- neither a partial write
474	     * (which still advances) nor a recoverable interruption (which reports
475	     * EINTR). The offered bytes are traced (when TRACE_BYTES is on) so the
476	     * test can verify the rejected key material never leaks. */
477	    if (cfg_write_zero_after >= 0) {
478	        long long remaining =
479	            (long long)cfg_write_zero_after - (long long)written_total[fd];
480	        if (remaining <= 0) {
481	            if (cfg_trace_bytes) {
482	                char *hex = hex_encode(buf, allowed);
483	                if (hex) {
484	                    trace("WRITE off=%llu req=%zu ret=0 hex=%s\n",
485	                          written_total[fd], allowed, hex);
486	                    free(hex);
487	                } else {
488	                    trace("WRITE off=%llu req=%zu ret=0\n",
489	                          written_total[fd], allowed);
490	                }
491	            } else {
492	                trace("WRITE off=%llu req=%zu ret=0\n",
493	                      written_total[fd], allowed);
494	            }
495	            return 0;
496	        }
497	        if (allowed > (size_t)remaining)
498	            allowed = (size_t)remaining;
499	    }
500	
501	    ssize_t r = real_write(fd, buf, allowed);
502	    if (r > 0) {
503	        unsigned long long off = written_total[fd];
504	        written_total[fd] += (unsigned long long)r;
505	        if (cfg_trace_bytes) {
506	            char *hex = hex_encode(buf, (size_t)r);
507	            if (hex) {
508	                trace("WRITE off=%llu req=%zu ret=%zd hex=%s\n",
509	                      off, allowed, r, hex);
510	                free(hex);
511	            } else {
512	                trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
513	            }
514	        } else {
515	            trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
516	        }
517	    } else {
518	        trace("WRITE off=%llu req=%zu ret=%zd\n",
519	              written_total[fd], allowed, r);
520	    }
521	    return r;
522	}
523	
524	int fsync(int fd)
525	{
526	    if (!real_fsync)
527	        real_fsync = (fsync_fn)dlsym(RTLD_NEXT, "fsync");
528	
529	    if (!process_active())
530	        return real_fsync(fd);
531	    load_config();
532	
533	    if (is_tracked(fd) && cfg_fail_fsync) {
534	        trace("FSYNC ret=-1\n");
535	        errno = EIO;
536	        return -1;
537	    }
538	
539	    int rc = real_fsync(fd);
540	    if (is_tracked(fd))
541	        trace("FSYNC ret=%d\n", rc);
542	    return rc;
543	}
544	
545	int close(int fd)
546	{
547	    if (!real_close)
548	        real_close = (close_fn)dlsym(RTLD_NEXT, "close");
549	
550	    if (!process_active() || !is_tracked(fd))
551	        return real_close(fd);
552	    load_config();
553	
554	    /*
555	     * Always really close first: on Linux the descriptor is released even
556	     * when close() reports an error, so an injected failure must be a
557	     * report on top of a released descriptor -- the guest must not retry
558	     * the close. Either way the fd is gone, so stop tracking it.
559	     */
560	    int rc = real_close(fd);
561	    tracked[fd] = 0;
562	    if (rc != 0) {
563	        trace("CLOSE ret=-1\n");
564	        return rc;
565	    }
566	    if (cfg_close_eintr) {
567	        /* The recoverable interruption: the descriptor is gone, only the
568	         * report says EINTR. */
569	        trace("CLOSE ret=-1 errno=EINTR\n");
570	        errno = EINTR;
571	        return -1;
572	    }
573	    if (cfg_fail_close) {
574	        trace("CLOSE ret=-1 errno=EIO\n");
575	        errno = EIO;
576	        return -1;
577	    }
578	    trace("CLOSE ret=0\n");
579	    return 0;
580	}
581	
582	int unlink(const char *path)
583	{
584	    if (!real_unlink)
585	        real_unlink = (unlink_fn)dlsym(RTLD_NEXT, "unlink");
586	
587	    if (!process_active())
588	        return real_unlink(path);
589	    load_config();
590	
591	    if (cfg_fail_unlink) {
592	        /* The system refuses the cleanup: nothing is removed. */
593	        trace("UNLINK ret=-1 errno=EACCES\n");
594	        errno = EACCES;
595	        return -1;
596	    }
597	    int rc = real_unlink(path);
598	    trace("UNLINK ret=%d\n", rc);
599	    return rc;
600	}
