/*
 * permfail.c -- LD_PRELOAD shim for wrapfile keygen permission tests.
 *
 * Two jobs:
 *
 * 1. Tracing. For the file the guest creates with open(O_CREAT|...) it logs
 *    to WRAPFILE_TEST_TRACE_FILE (one line per event):
 *
 *      BORN        fd=N mode=0oNNNN   mode right after the creating open()
 *      FCHMOD      ret=0/-1 mode=0oNNNN
 *      FSTAT       ret=0/-1 mode=0oNNNN size=N   (mode reported to guest)
 *      FIRST_WRITE mode=0oNNNN size=N  immediately before the first write()
 *      WRITE       off=N req=N ret=N [hex=...]   each write() on the key fd;
 *                    ret=-1 errno=ENAME for injected faults
 *      FSYNC       ret=0/-1
 *      CLOSE       ret=0/-1 [errno=ENAME]   close() on the key fd; the
 *                    descriptor is really released either way (Linux
 *                    semantics), errno= marks an injected report
 *      UNLINK      ret=0/-1 [errno=ENAME]   each unlink() the guest attempts
 *
 *    FIRST_WRITE with mode=0o600 and size=0 proves the program had both set
 *    and *confirmed* 0600 before a single key byte was written. The WRITE
 *    stream (off ascending from 0 with no gaps or overlaps, ending at 32)
 *    proves partial writes were resumed without duplicating or dropping
 *    bytes, and FSYNC ret=0 after the last WRITE proves the key was synced
 *    to disk before the program reported success.
 *
 * 2. Fault injection (only for a descriptor the guest itself created):
 *      WRAPFILE_TEST_FAIL_FCHMOD=1      fchmod() fails with EPERM
 *      WRAPFILE_TEST_FAIL_FSTAT=1       fstat()/fstat64() fail (EBADF), so the
 *                                        resulting mode cannot be confirmed
 *      WRAPFILE_TEST_LIE_MODE=OCTAL     fstat reports these low 12 mode bits
 *                                        (e.g. 0000) while the real fchmod
 *                                        succeeded -- a filesystem that silently
 *                                        stores another mode
 *      WRAPFILE_TEST_PARTIAL_WRITE=N    write() accepts at most N bytes per
 *                                        call (a kernel that only takes part
 *                                        of the buffer)
 *      WRAPFILE_TEST_WRITE_EINTR=N      the first N write() calls fail with
 *                                        EINTR, then writes succeed normally
 *      WRAPFILE_TEST_FAIL_WRITE_AFTER=N after N bytes in total have landed,
 *                                        write() fails with EIO (the last
 *                                        partial write is clamped so exactly
 *                                        N bytes are on disk before the error)
 *      WRAPFILE_TEST_WRITE_ZERO_AFTER=N once N bytes in total have landed,
 *                                        write() returns 0 without setting
 *                                        errno: no progress, yet no error
 *                                        either (the last real write is
 *                                        clamped so exactly N bytes are on
 *                                        disk first). Distinct from
 *                                        PARTIAL_WRITE (some progress every
 *                                        call) and from EINTR/EIO (an error
 *                                        is reported).
 *      WRAPFILE_TEST_FAIL_FSYNC=1       fsync() fails with EIO
 *      WRAPFILE_TEST_FAIL_CLOSE=1       close() on the key fd reports EIO.
 *                                       The descriptor is really closed
 *                                       first (on Linux a failed close()
 *                                       still releases it), so the guest
 *                                       must not retry the close
 *      WRAPFILE_TEST_CLOSE_EINTR=1      close() on the key fd reports EINTR
 *                                       after really releasing the
 *                                       descriptor -- the recoverable
 *                                       interruption, not a failure
 *      WRAPFILE_TEST_FAIL_UNLINK=1      unlink() fails with EACCES without
 *                                       removing anything (the system
 *                                       refuses the cleanup)
 *      WRAPFILE_TEST_TRACE_BYTES=1      append hex=... of the bytes each
 *                                        write() actually landed, so tests can
 *                                        reconstruct the byte stream and check
 *                                        nothing secret leaks to stdout/stderr
 *
 * The shim only activates inside an executable whose basename starts with
 * "wrapfile" (checked via /proc/self/exe), so a wrapper shell used to set
 * the umask is never affected. After execve() the guest starts with a fresh
 * table, so only the guest's own O_CREAT descriptor (the key file) is
 * tracked; stdout/stderr and unrelated fds pass through untouched.
 */

#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <unistd.h>

#ifndef O_CLOEXEC
#define O_CLOEXEC 0
#endif

typedef int (*open_fn)(const char *, int, ...);
typedef int (*open64_fn)(const char *, int, ...);
typedef int (*fchmod_fn)(int, mode_t);
typedef int (*fstat_fn)(int, struct stat *);
typedef int (*fstat64_fn)(int, struct stat64 *);
typedef ssize_t (*write_fn)(int, const void *, size_t);
typedef int (*fsync_fn)(int);
typedef int (*close_fn)(int);
typedef int (*unlink_fn)(const char *);

static open_fn    real_open;
static open64_fn  real_open64;
static fchmod_fn  real_fchmod;
static fstat_fn   real_fstat;
static fstat64_fn real_fstat64;
static write_fn   real_write;
static fsync_fn   real_fsync;
static close_fn   real_close;
static unlink_fn  real_unlink;

static int cfg_fail_fchmod = 0;
static int cfg_fail_fstat  = 0;
static int cfg_lie_mode    = -1; /* -1 = disabled */
static long cfg_partial_write = 0;      /* 0 = disabled */
static int  cfg_write_eintr = 0;        /* first N write() calls fail EINTR */
static long cfg_fail_write_after = -1;  /* -1 = disabled */
static long cfg_write_zero_after = -1;  /* -1 = disabled */
static int  cfg_fail_fsync = 0;
static int  cfg_fail_close = 0;
static int  cfg_close_eintr = 0;
static int  cfg_fail_unlink = 0;
static int  cfg_trace_bytes = 0;

/* Descriptor table: fds the guest created with O_CREAT. */
#define FD_MAX 1024
static unsigned char tracked[FD_MAX];
static unsigned char written[FD_MAX];
static unsigned char eintr_left[FD_MAX];
static unsigned long long written_total[FD_MAX];

/* ----- activation: only inside the wrapfile executable ----- */

static int process_active(void)
{
    static int cached = -1;
    if (cached != -1)
        return cached;

    char buf[512];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (n <= 0) {
        cached = 0;
        return 0;
    }
    buf[n] = '\0';
    const char *base = strrchr(buf, '/');
    base = base ? base + 1 : buf;
    cached = (strncmp(base, "wrapfile", 8) == 0) ? 1 : 0;
    return cached;
}

static void load_config(void)
{
    static int loaded = 0;
    if (loaded)
        return;
    loaded = 1;

    const char *v;
    if ((v = getenv("WRAPFILE_TEST_FAIL_FCHMOD")) && v[0] == '1')
        cfg_fail_fchmod = 1;
    if ((v = getenv("WRAPFILE_TEST_FAIL_FSTAT")) && v[0] == '1')
        cfg_fail_fstat = 1;
    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")))
        (void)v; /* opened lazily on first trace() */
    if ((v = getenv("WRAPFILE_TEST_LIE_MODE")) && v[0] != '\0')
        cfg_lie_mode = (int)strtol(v, NULL, 8);
    if ((v = getenv("WRAPFILE_TEST_PARTIAL_WRITE")) && v[0] != '\0')
        cfg_partial_write = strtol(v, NULL, 10);
    if ((v = getenv("WRAPFILE_TEST_WRITE_EINTR")) && v[0] != '\0')
        cfg_write_eintr = atoi(v);
    if ((v = getenv("WRAPFILE_TEST_FAIL_WRITE_AFTER")) && v[0] != '\0')
        cfg_fail_write_after = strtol(v, NULL, 10);
    if ((v = getenv("WRAPFILE_TEST_WRITE_ZERO_AFTER")) && v[0] != '\0')
        cfg_write_zero_after = strtol(v, NULL, 10);
    if ((v = getenv("WRAPFILE_TEST_FAIL_FSYNC")) && v[0] == '1')
        cfg_fail_fsync = 1;
    if ((v = getenv("WRAPFILE_TEST_FAIL_CLOSE")) && v[0] == '1')
        cfg_fail_close = 1;
    if ((v = getenv("WRAPFILE_TEST_CLOSE_EINTR")) && v[0] == '1')
        cfg_close_eintr = 1;
    if ((v = getenv("WRAPFILE_TEST_FAIL_UNLINK")) && v[0] == '1')
        cfg_fail_unlink = 1;
    if ((v = getenv("WRAPFILE_TEST_TRACE_BYTES")) && v[0] == '1')
        cfg_trace_bytes = 1;
}

static int trace_fd(void)
{
    static int fd = -2; /* -2 = not initialised */
    if (fd != -2)
        return fd;

    const char *path = getenv("WRAPFILE_TEST_TRACE_FILE");
    if (!path || !path[0]) {
        fd = -1;
        return fd;
    }
    /*
     * Raw openat(AT_FDCWD, ...) syscall rather than open(): going through
     * our own open() wrapper inside the wrapfile process would mark the
     * trace file as a tracked, created descriptor and mis-attribute writes
     * to it. The syscall bypasses all libc interposition.
     */
    fd = (int)syscall(SYS_openat, AT_FDCWD, path,
                      O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);
    return fd;
}

static void trace(const char *fmt, ...)
{
    int fd = trace_fd();
    if (fd < 0)
        return;
    va_list ap;
    va_start(ap, fmt);
    vdprintf(fd, fmt, ap);
    va_end(ap);
}

/* ----- per-descriptor helpers ----- */

static fstat_fn get_real_fstat(void)
{
    if (!real_fstat)
        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
    return real_fstat;
}

static int is_tracked(int fd)
{
    return fd >= 0 && fd < FD_MAX && tracked[fd];
}

/* malloc'd lowercase hex of n bytes, or NULL. Caller frees. */
static char *hex_encode(const unsigned char *p, size_t n)
{
    static const char digits[] = "0123456789abcdef";
    char *hex = malloc(n * 2 + 1);
    if (!hex)
        return NULL;
    for (size_t i = 0; i < n; i++) {
        hex[i * 2] = digits[p[i] >> 4];
        hex[i * 2 + 1] = digits[p[i] & 0xf];
    }
    hex[n * 2] = '\0';
    return hex;
}

static void note_created(int fd)
{
    if (fd < 0 || fd >= FD_MAX)
        return;
    tracked[fd] = 1;
    written[fd] = 0;
    eintr_left[fd] = (cfg_write_eintr > 0 && cfg_write_eintr < 256)
                         ? (unsigned char)cfg_write_eintr
                         : 0;
    written_total[fd] = 0;

    struct stat st;
    fstat_fn fn = get_real_fstat();
    if (fn && fn(fd, &st) == 0) {
        trace("BORN fd=%d mode=0%04o\n", fd,
              (unsigned)(st.st_mode & 07777));
    }
}

/*
 * Shared fstat handling for tracked fds: perform the real fstat (via the
 * passed function), apply fault/lie policy, log the result, and tell the
 * caller what to return.
 */
static int handle_fstat(int fd, void *st, int is64)
{
    int rc = is64 ? real_fstat64(fd, (struct stat64 *)st)
                  : real_fstat(fd, (struct stat *)st);

    if (!is_tracked(fd))
        return rc;

    if (rc != 0) {
        trace("FSTAT ret=-1 mode=00000 size=0\n");
        return rc;
    }

    mode_t real_mode;
    off_t real_size;
    if (is64) {
        struct stat64 *s = (struct stat64 *)st;
        real_mode = s->st_mode;
        real_size = s->st_size;
    } else {
        struct stat *s = (struct stat *)st;
        real_mode = s->st_mode;
        real_size = s->st_size;
    }

    if (cfg_fail_fstat) {
        trace("FSTAT ret=-1 mode=0%04o size=%lld\n",
              (unsigned)(real_mode & 07777), (long long)real_size);
        errno = EBADF;
        return -1;
    }

    mode_t reported = real_mode;
    if (cfg_lie_mode >= 0) {
        reported = (real_mode & ~(mode_t)07777) | (mode_t)cfg_lie_mode;
        if (is64)
            ((struct stat64 *)st)->st_mode = reported;
        else
            ((struct stat *)st)->st_mode = reported;
    }

    trace("FSTAT ret=0 mode=0%04o size=%lld\n",
          (unsigned)(reported & 07777), (long long)real_size);
    return 0;
}

/* ----- intercepted libc functions ----- */

int open(const char *path, int flags, ...)
{
    if (!real_open)
        real_open = (open_fn)dlsym(RTLD_NEXT, "open");

    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap;
        va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }

    int fd = real_open(path, flags, mode);

    if (process_active() && (flags & O_CREAT)) {
        load_config();
        if (fd >= 0)
            note_created(fd);
        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
              (unsigned)(mode & 07777));
    }
    return fd;
}

int open64(const char *path, int flags, ...)
{
    if (!real_open64)
        real_open64 = (open64_fn)dlsym(RTLD_NEXT, "open64");

    mode_t mode = 0;
    if (flags & O_CREAT) {
        va_list ap;
        va_start(ap, flags);
        mode = va_arg(ap, mode_t);
        va_end(ap);
    }

    int fd = real_open64(path, flags, mode);

    if (process_active() && (flags & O_CREAT)) {
        load_config();
        if (fd >= 0)
            note_created(fd);
        trace("OPEN ret=%d flags=0%o mode=0%04o\n", fd, flags,
              (unsigned)(mode & 07777));
    }
    return fd;
}

int fchmod(int fd, mode_t mode)
{
    if (!real_fchmod)
        real_fchmod = (fchmod_fn)dlsym(RTLD_NEXT, "fchmod");

    if (!process_active())
        return real_fchmod(fd, mode);
    load_config();

    if (is_tracked(fd) && cfg_fail_fchmod) {
        trace("FCHMOD ret=-1 mode=0%04o\n", (unsigned)(mode & 07777));
        errno = EPERM;
        return -1;
    }

    int rc = real_fchmod(fd, mode);
    if (is_tracked(fd)) {
        trace("FCHMOD ret=%d mode=0%04o\n", rc,
              (unsigned)(mode & 07777));
    }
    return rc;
}

int fstat(int fd, struct stat *st)
{
    if (!real_fstat)
        real_fstat = (fstat_fn)dlsym(RTLD_NEXT, "fstat");
    if (!process_active())
        return real_fstat(fd, st);
    load_config();
    if (!is_tracked(fd))
        return real_fstat(fd, st);
    return handle_fstat(fd, st, 0);
}

int fstat64(int fd, struct stat64 *st)
{
    if (!real_fstat64)
        real_fstat64 = (fstat64_fn)dlsym(RTLD_NEXT, "fstat64");
    if (!process_active())
        return real_fstat64(fd, st);
    load_config();
    if (!is_tracked(fd))
        return real_fstat64(fd, st);
    return handle_fstat(fd, st, 1);
}

ssize_t write(int fd, const void *buf, size_t count)
{
    if (!real_write)
        real_write = (write_fn)dlsym(RTLD_NEXT, "write");

    if (!process_active() || !is_tracked(fd))
        return real_write(fd, buf, count);
    load_config();

    if (!written[fd]) {
        written[fd] = 1;
        struct stat st;
        fstat_fn fn = get_real_fstat();
        if (fn && fn(fd, &st) == 0) {
            trace("FIRST_WRITE mode=0%04o size=%lld\n",
                  (unsigned)(st.st_mode & 07777),
                  (long long)st.st_size);
        } else {
            trace("FIRST_WRITE mode=unknown size=unknown\n");
        }
    }

    /* A recoverable interruption: the call fails before any byte is
     * consumed, and the next call succeeds. */
    if (eintr_left[fd] > 0) {
        eintr_left[fd]--;
        trace("WRITE ret=-1 errno=EINTR\n");
        errno = EINTR;
        return -1;
    }

    /* A kernel that only accepts part of the buffer per call. */
    size_t allowed = count;
    if (cfg_partial_write > 0 && allowed > (size_t)cfg_partial_write)
        allowed = (size_t)cfg_partial_write;

    /* An unrecoverable error once N bytes have landed. */
    if (cfg_fail_write_after >= 0) {
        long long remaining =
            (long long)cfg_fail_write_after - (long long)written_total[fd];
        if (remaining <= 0) {
            trace("WRITE ret=-1 errno=EIO off=%llu\n", written_total[fd]);
            errno = EIO;
            return -1;
        }
        if (allowed > (size_t)remaining)
            allowed = (size_t)remaining;
    }

    /* No progress and no error: once N bytes have landed, write() accepts
     * 0 bytes and reports success-with-zero -- neither a partial write
     * (which still advances) nor a recoverable interruption (which reports
     * EINTR). The offered bytes are traced (when TRACE_BYTES is on) so the
     * test can verify the rejected key material never leaks. */
    if (cfg_write_zero_after >= 0) {
        long long remaining =
            (long long)cfg_write_zero_after - (long long)written_total[fd];
        if (remaining <= 0) {
            if (cfg_trace_bytes) {
                char *hex = hex_encode(buf, allowed);
                if (hex) {
                    trace("WRITE off=%llu req=%zu ret=0 hex=%s\n",
                          written_total[fd], allowed, hex);
                    free(hex);
                } else {
                    trace("WRITE off=%llu req=%zu ret=0\n",
                          written_total[fd], allowed);
                }
            } else {
                trace("WRITE off=%llu req=%zu ret=0\n",
                      written_total[fd], allowed);
            }
            return 0;
        }
        if (allowed > (size_t)remaining)
            allowed = (size_t)remaining;
    }

    ssize_t r = real_write(fd, buf, allowed);
    if (r > 0) {
        unsigned long long off = written_total[fd];
        written_total[fd] += (unsigned long long)r;
        if (cfg_trace_bytes) {
            char *hex = hex_encode(buf, (size_t)r);
            if (hex) {
                trace("WRITE off=%llu req=%zu ret=%zd hex=%s\n",
                      off, allowed, r, hex);
                free(hex);
            } else {
                trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
            }
        } else {
            trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
        }
    } else {
        trace("WRITE off=%llu req=%zu ret=%zd\n",
              written_total[fd], allowed, r);
    }
    return r;
}

int fsync(int fd)
{
    if (!real_fsync)
        real_fsync = (fsync_fn)dlsym(RTLD_NEXT, "fsync");

    if (!process_active())
        return real_fsync(fd);
    load_config();

    if (is_tracked(fd) && cfg_fail_fsync) {
        trace("FSYNC ret=-1\n");
        errno = EIO;
        return -1;
    }

    int rc = real_fsync(fd);
    if (is_tracked(fd))
        trace("FSYNC ret=%d\n", rc);
    return rc;
}

int close(int fd)
{
    if (!real_close)
        real_close = (close_fn)dlsym(RTLD_NEXT, "close");

    if (!process_active() || !is_tracked(fd))
        return real_close(fd);
    load_config();

    /*
     * Always really close first: on Linux the descriptor is released even
     * when close() reports an error, so an injected failure must be a
     * report on top of a released descriptor -- the guest must not retry
     * the close. Either way the fd is gone, so stop tracking it.
     */
    int rc = real_close(fd);
    tracked[fd] = 0;
    if (rc != 0) {
        trace("CLOSE ret=-1\n");
        return rc;
    }
    if (cfg_close_eintr) {
        /* The recoverable interruption: the descriptor is gone, only the
         * report says EINTR. */
        trace("CLOSE ret=-1 errno=EINTR\n");
        errno = EINTR;
        return -1;
    }
    if (cfg_fail_close) {
        trace("CLOSE ret=-1 errno=EIO\n");
        errno = EIO;
        return -1;
    }
    trace("CLOSE ret=0\n");
    return 0;
}

int unlink(const char *path)
{
    if (!real_unlink)
        real_unlink = (unlink_fn)dlsym(RTLD_NEXT, "unlink");

    if (!process_active())
        return real_unlink(path);
    load_config();

    if (cfg_fail_unlink) {
        /* The system refuses the cleanup: nothing is removed. */
        trace("UNLINK ret=-1 errno=EACCES\n");
        errno = EACCES;
        return -1;
    }
    int rc = real_unlink(path);
    trace("UNLINK ret=%d\n", rc);
    return rc;
}

//! Shared helpers for the keygen regression tests: build the LD_PRELOAD
//! fault-injection shims (tests/support/permfail, tests/support/randtrap)
//! on demand, at test time.
//!
//! The shims are compiled here rather than by a Cargo build script so that
//! `cargo build` / `cargo build --release` never invoke a C compiler: a
//! machine that can compile and link wrapfile itself always gets a working
//! binary, regardless of whether the test-only C toolchain is present or
//! functional. The price is that the shim-backed tests must cope with a
//! missing compiler themselves. The policy, matching the old build script:
//!
//! * Platform without shim support (non-Linux for permfail; non-Linux or
//!   non-x86_64/aarch64 for randtrap): return `None` after printing the
//!   reason; the dependent tests skip, everything else still runs.
//! * C compiler not found: same -- skip with the reason printed.
//! * The compiler *ran* but rejected the shim source: this is a real
//!   problem (broken headers, broken source, test-only compiler settings),
//!   never "platform unsupported" -- panic, failing the test run with the
//!   compile stage and the compiler's own diagnostics.
//!
//! Compilation intentionally invokes the system C compiler directly instead
//! of pulling in the `cc` crate, so the offline dependency set
//! (getrandom + libc) is unchanged and `cargo test --offline` keeps working.
#![allow(dead_code)]

use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::OnceLock;

/// Path to the permfail shim, building it on first use. `None` (with the
/// reason on stderr) when this platform or machine cannot provide it.
pub fn permfail_so() -> Option<PathBuf> {
    // The permfail shim relies on glibc's open/open64/fstat/fstat64
    // interposition semantics; build it on Linux only.
    static SO: OnceLock<Option<PathBuf>> = OnceLock::new();
    SO.get_or_init(|| {
        if std::env::consts::OS != "linux" {
            eprintln!(
                "permfail shim unavailable: only supported on Linux/glibc, \
                 this target is {}",
                std::env::consts::OS
            );
            return None;
        }
        build_shim(
            "permfail",
            "libwrapfile_permfail.so",
            "tests/support/permfail/permfail.c",
        )
    })
    .clone()
}

/// Path to the randtrap shim, building it on first use. `None` (with the
/// reason on stderr) when this platform or machine cannot provide it.
pub fn randtrap_so() -> Option<PathBuf> {
    // The randtrap shim relies on seccomp SECCOMP_RET_TRAP plus
    // signal-frame register access (x86_64 and aarch64 only).
    static SO: OnceLock<Option<PathBuf>> = OnceLock::new();
    SO.get_or_init(|| {
        if std::env::consts::OS != "linux" {
            eprintln!(
                "randtrap shim unavailable: only supported on Linux, \
                 this target is {}",
                std::env::consts::OS
            );
            return None;
        }
        if !matches!(std::env::consts::ARCH, "x86_64" | "aarch64") {
            eprintln!(
                "randtrap shim unavailable: only supported on x86_64/aarch64, \
                 this target is {}",
                std::env::consts::ARCH
            );
            return None;
        }
        build_shim(
            "randtrap",
            "libwrapfile_randtrap.so",
            "tests/support/randtrap/randtrap.c",
        )
    })
    .clone()
}

/// Path to the keylife observer executable, building it on first use.
/// `None` (with the reason on stderr) when this platform or machine cannot
/// provide it.
///
/// Unlike the two shims this is a standalone program (not an LD_PRELOAD
/// library): it forks, has its child traceme+exec the real wrapfile, and
/// watches the temporary key buffer from outside with ptrace. It is
/// therefore linked as an ordinary executable, not as a `-shared` object.
pub fn keylife_bin() -> Option<PathBuf> {
    // PTRACE_GET_SYSCALL_INFO and the seccomp/SIGSYS interaction it relies
    // on are Linux-only, and the register/insn decoding covers the same two
    // architectures as the randtrap shim.
    static BIN: OnceLock<Option<PathBuf>> = OnceLock::new();
    BIN.get_or_init(|| {
        if std::env::consts::OS != "linux" {
            eprintln!(
                "keylife observer unavailable: only supported on Linux, \
                 this target is {}",
                std::env::consts::OS
            );
            return None;
        }
        if !matches!(std::env::consts::ARCH, "x86_64" | "aarch64") {
            eprintln!(
                "keylife observer unavailable: only supported on \
                 x86_64/aarch64, this target is {}",
                std::env::consts::ARCH
            );
            return None;
        }
        build_support_exe(
            "keylife",
            "keylife-observer",
            "tests/support/keylife/keylife.c",
        )
    })
    .clone()
}

/// Compile one shim with the system C compiler. Returns the built path, or
/// `None` (reason printed) when no C compiler exists on this machine. A
/// compiler that starts but fails to build the shim is a hard error.
fn build_shim(label: &str, so_name: &str, src_rel: &str) -> Option<PathBuf> {
    let src = Path::new(env!("CARGO_MANIFEST_DIR")).join(src_rel);

    // Build into a per-process directory so concurrently running test
    // binaries never write the same .so. Prefer Cargo's own scratch area
    // (cleaned up with `target/`); fall back to the system temp dir.
    let dir = option_env!("CARGO_TARGET_TMPDIR")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join(format!("wrapfile-test-shims-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap_or_else(|e| {
        panic!("cannot create test shim build directory {}: {e}", dir.display())
    });
    let so = dir.join(so_name);

    let cc = std::env::var("CC").unwrap_or_else(|_| "cc".to_string());
    let output = Command::new(&cc)
        .args(["-O0", "-g", "-fPIC", "-shared", "-Wall", "-Wextra"])
        .arg("-o")
        .arg(&so)
        .arg(&src)
        .output();

    match output {
        Ok(o) if o.status.success() => Some(so),
        // The compiler started but the shim did not build: fail loudly,
        // naming the compile stage and relaying the compiler's diagnostics.
        // This must never be mistaken for an unsupported platform.
        Ok(o) => panic!(
            "test shim '{label}' failed to compile: `{cc}` exited with {} \
             while building {src_rel}\ncompiler stderr:\n{}",
            o.status,
            String::from_utf8_lossy(&o.stderr),
        ),
        // A machine without a C compiler can still build and use wrapfile
        // itself; the shim-backed tests skip with the reason stated.
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            eprintln!(
                "{label} shim not built: C compiler '{cc}' not found; \
                 install a C compiler to run the shim-backed tests"
            );
            None
        }
        Err(e) => panic!("failed to run C compiler '{cc}' while building test shim '{label}': {e}"),
    }
}

/// Compile one test-only support *executable* (rather than an LD_PRELOAD
/// shared object) with the system C compiler. Same skip/fail policy as
/// `build_shim`: no compiler -> `None` (skip with the reason printed); a
/// compiler that ran but rejected the source -> hard panic.
///
/// The executable's name must not start with "wrapfile": the randtrap and
/// permfail shims arm themselves from the guest executable's basename, and
/// the observer is launched with those shims in LD_PRELOAD (it then
/// fork/execs the real wrapfile, where they *should* arm).
fn build_support_exe(label: &str, exe_name: &str, src_rel: &str) -> Option<PathBuf> {
    let src = Path::new(env!("CARGO_MANIFEST_DIR")).join(src_rel);

    // Same per-process scratch directory policy as build_shim, so parallel
    // test binaries never overwrite one another's observer.
    let dir = option_env!("CARGO_TARGET_TMPDIR")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join(format!("wrapfile-test-shims-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap_or_else(|e| {
        panic!("cannot create test shim build directory {}: {e}", dir.display())
    });
    let exe = dir.join(exe_name);

    let cc = std::env::var("CC").unwrap_or_else(|_| "cc".to_string());
    let output = Command::new(&cc)
        // -O2 so the observer itself is quick (it single-steps the guest);
        // no -shared: this is a normal executable that links libc.
        .args(["-O2", "-g", "-Wall", "-Wextra"])
        .arg("-o")
        .arg(&exe)
        .arg(&src)
        .output();

    match output {
        Ok(o) if o.status.success() => Some(exe),
        Ok(o) => panic!(
            "test support program '{label}' failed to compile: `{cc}` exited \
             with {} while building {src_rel}\ncompiler stderr:\n{}",
            o.status,
            String::from_utf8_lossy(&o.stderr),
        ),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            eprintln!(
                "{label} support program not built: C compiler '{cc}' not \
                 found; install a C compiler to run the memory-zeroing tests"
            );
            None
        }
        Err(e) => panic!(
            "failed to run C compiler '{cc}' while building test support \
             program '{label}': {e}"
        ),
    }
}

