172	fn parse_trace(path: &Path) -> Vec<Event> {
173	    let text = fs::read_to_string(path).unwrap();
174	    text.lines()
175	        .map(|line| {
176	            let mut it = line.split_whitespace();
177	            let kind = it.next().unwrap_or("").to_string();
178	            let attrs = it
179	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
180	                .collect();
181	            Event { kind, attrs }
182	        })
183	        .collect()
184	}
