186	/// Create the trace file up front (mode 0644) so that it stays readable even
187	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
188	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
189	    let p = dir.join(name);
190	    fs::File::create(&p).unwrap();
191	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
192	    p
193	}
