195	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
196	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
197	    events
198	        .iter()
199	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
200	        .map(|e| {
201	            (
202	                e.off().expect("WRITE event needs off="),
203	                e.ret().unwrap() as u64,
204	                e.hex_bytes(),
205	            )
206	        })
207	        .collect()
208	}
209	
210	/// The landed writes must tile [0, total) exactly: the first starts at 0,
211	/// each continues where the previous ended -- no byte written twice, none
212	/// skipped.
213	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
214	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
215	    let mut expect = 0u64;
216	    for (off, n, _) in writes {
217	        assert_eq!(
218	            *off, expect,
219	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
220	        );
221	        expect += n;
222	    }
223	    assert_eq!(
224	        expect as usize, total,
225	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
226	    );
227	}
228	
229	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
230	    writes
231	        .iter()
232	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
233	        .collect()
234	}
235	
236	/// The write() calls that accepted 0 bytes while reporting no error.
237	fn zero_writes<'a>(events: &'a [Event]) -> Vec<&'a Event> {
238	    events
239	        .iter()
240	        .filter(|e| e.kind == "WRITE" && e.ret() == Some(0))
241	        .collect()
242	}
243	
244	/// Bytes the program handed to write() calls that accepted none of them.
245	fn rejected_offerings(events: &[Event]) -> Vec<u8> {
246	    zero_writes(events)
247	        .iter()
248	        .flat_map(|e| e.hex_bytes().expect("TRACE_BYTES must be on"))
249	        .collect()
250	}
