264	/// The full success contract: exit 0, empty stderr, only the save-location
265	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
266	/// nowhere.
267	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
268	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
269	    assert!(
270	        run.err.is_empty(),
271	        "stderr must be empty on success, got {}",
272	        String::from_utf8_lossy(&run.err)
273	    );
274	    assert_eq!(
275	        run.out,
276	        format!("Key saved to {}\n", key.display()).into_bytes(),
277	        "stdout must be exactly the save-location message"
278	    );
279	
280	    let meta = fs::metadata(key).expect("key file must exist on success");
281	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
282	    assert_eq!(
283	        meta.mode() & 0o7777,
284	        MODE_0600,
285	        "key file mode must be exactly 0600"
286	    );
287	
288	    let bytes = fs::read(key).unwrap();
289	    assert_eq!(bytes.len(), KEY_LEN);
290	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
291	    assert!(
292	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
293	        "key bytes must never appear on stdout/stderr"
294	    );
295	    bytes
296	}
