298	/// The failure contract shared by the write-error and fsync-error tests:
299	/// exit 1, an explanation on stderr, no success output, no leaked key
300	/// material, and no trace of this invocation left in the parent directory.
301	fn assert_failed_cleanly(
302	    key: &Path,
303	    run: &Run,
304	    dir: &Path,
305	    allowed_entries: &[&str],
306	    leaked_candidate: &[u8],
307	) {
308	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
309	    assert!(
310	        run.out.is_empty(),
311	        "no success message may be printed on failure, got {}",
312	        String::from_utf8_lossy(&run.out)
313	    );
314	    assert!(!run.err.is_empty(), "stderr must explain the failure");
315	    let stderr = String::from_utf8_lossy(&run.err);
316	    assert!(
317	        stderr.contains(&key.display().to_string()),
318	        "stderr should name the target path, got: {stderr}"
319	    );
320	    assert!(
321	        !contains_slice(&run.out, leaked_candidate)
322	            && !contains_slice(&run.err, leaked_candidate),
323	        "key material must never leak to stdout/stderr, even on failure"
324	    );
325	
326	    assert!(
327	        !key.exists(),
328	        "the file this invocation created must be removed after the failure"
329	    );
330	    let mut leftovers: Vec<String> = fs::read_dir(dir)
331	        .unwrap()
332	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
333	        .filter(|n| !allowed_entries.contains(&n.as_str()))
334	        .collect();
335	    leftovers.sort();
336	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
337	}
