339	/// Key material must not surface on stdout/stderr in any encoding: not as
340	/// raw bytes, and not as a hex (or other text) rendering.
341	fn assert_key_material_not_leaked(run: &Run, material: &[u8], what: &str) {
342	    assert!(
343	        !contains_slice(&run.out, material) && !contains_slice(&run.err, material),
344	        "{what} must never appear on stdout/stderr as raw bytes"
345	    );
346	    let hex: String = material.iter().map(|b| format!("{b:02x}")).collect();
347	    let out = String::from_utf8_lossy(&run.out);
348	    let err = String::from_utf8_lossy(&run.err);
349	    assert!(
350	        !out.contains(&hex) && !err.contains(&hex),
351	        "{what} must never appear on stdout/stderr in hex form"
352	    );
353	}
