355	/// The contract when the save fails AND the system refuses to remove this
356	/// run's file: exit 1, empty stdout, stderr names the target, keeps the
357	/// original failure reason (`stage_reason`), reports the refused cleanup,
358	/// and warns that this run's file may remain -- and the file really does
359	/// remain, with nothing stashed under another name.
360	fn assert_failed_with_residue(
361	    key: &Path,
362	    run: &Run,
363	    dir: &Path,
364	    allowed_entries: &[&str],
365	    stage_reason: &str,
366	) {
367	    assert_eq!(run.rc, 1, "a failed save with refused cleanup must exit 1");
368	    assert!(
369	        run.out.is_empty(),
370	        "no success message may be printed, got {}",
371	        String::from_utf8_lossy(&run.out)
372	    );
373	    let stderr = String::from_utf8_lossy(&run.err);
374	    assert!(
375	        stderr.contains(&key.display().to_string()),
376	        "stderr should name the target path, got: {stderr}"
377	    );
378	    // The original failure reason is still reported...
379	    assert!(
380	        stderr.contains(stage_reason),
381	        "stderr must keep the original failure reason ({stage_reason:?}), got: {stderr}"
382	    );
383	    // ...the cleanup failure is reported too (not silently dropped, and not
384	    // replacing the save error)...
385	    assert!(
386	        stderr.contains("cleanup"),
387	        "stderr must report the failed cleanup, got: {stderr}"
388	    );
389	    // ...and the user is told this run's file may remain -- never that it
390	    // is gone.
391	    assert!(
392	        stderr.contains("may still be present"),
393	        "stderr must warn that this run's file may remain, got: {stderr}"
394	    );
395	
396	    // The refused removal means this run's file really is still at the
397	    // target -- the warning above is what keeps it from being mistaken for
398	    // a successfully saved key.
399	    assert!(
400	        key.exists(),
401	        "with unlink refused, this run's file remains at the target"
402	    );
403	    // Nothing was stashed under another name and no other residue appeared.
404	    let mut expected: Vec<String> = allowed_entries.iter().map(|s| s.to_string()).collect();
405	    expected.push(key.file_name().unwrap().to_string_lossy().into_owned());
406	    expected.sort();
407	    let mut entries: Vec<String> = fs::read_dir(dir)
408	        .unwrap()
409	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
410	        .collect();
411	    entries.sort();
412	    assert_eq!(entries, expected, "no renamed copy or other leftover may appear");
413	}
