415	// A pre-existing object that must survive a failed keygen byte-for-byte.
416	struct Sentinel {
417	    path: PathBuf,
418	    bytes: Vec<u8>,
419	    mode: u32,
420	    inode: u64,
421	}
422	
423	impl Sentinel {
424	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
425	        let path = dir.join(name);
426	        fs::write(&path, bytes).unwrap();
427	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
428	        let meta = fs::metadata(&path).unwrap();
429	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
430	    }
431	
432	    fn assert_untouched(&self) {
433	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
434	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
435	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
436	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
437	    }
438	}
