491	            .unwrap();
492	        let fsynced = events
493	            .iter()
494	            .position(|e| e.kind == "FSYNC" && e.ret() == Some(0))
495	            .expect("the key must be fsynced before success is reported");
496	        assert!(fsynced > last_write, "fsync must follow the last write");
497	    }
