    let out_text = String::from_utf8_lossy(out);
    let err_text = String::from_utf8_lossy(err);
    assert!(
        !out_text.contains(&hex) && !err_text.contains(&hex),
        "the key must never appear on stdout/stderr in hex form"
    );
}

